-- UPDATE preguntas.explicacion (generadas via Groq)
-- Fuente: ingesta/explicaciones_generadas.json (207 registros)

BEGIN;

DO $$
DECLARE
  sin_explicacion_antes int;
BEGIN
  SELECT COUNT(*) INTO sin_explicacion_antes
    FROM public.preguntas WHERE explicacion IS NULL OR explicacion = '';
  IF sin_explicacion_antes != 207 THEN
    RAISE EXCEPTION 'Se esperaban 207 preguntas sin explicacion (segun el JSON), hay % -- abortando para no pisar filas con otro motivo.', sin_explicacion_antes;
  END IF;
END $$;

UPDATE public.preguntas AS p
SET explicacion = v.explicacion
FROM (VALUES
  (208, 'El empleo de aciloximetilésteres en lugar de ésteres simples favorece la bioactivación porque el grupo oximato enlazado al carbonilo forma un enlace que es reconocido y hidrolizado con mayor facilidad por las esterasas, facilitando la liberación del ácido carboxílico activo en el sitio de acción; por tanto la opción C describe la ventaja específica de que el grupo éster externo es más accesible al centro activo de las esterasas. Las alternativas A y B se refieren a una supuesta disminución de la velocidad de hidrólisis o a una mayor estabilidad del profármaco, lo cual es contrario al objetivo de los aciloximetilésteres, que están diseñados para ser hidrolizados más rápidamente, y la opción D, aunque suena plausible, no distingue la característica particular de los oximetilésteres, pues la bioactivación selectiva no se logra únicamente por la presencia de dicho grupo.'),
  (209, 'El inconveniente de emplear bases de Mannich como profármacos de amidas radica en su inestabilidad in vitro, ya que la reacción de Mannich genera enlaces C–N que son susceptibles a hidrólisis y a la degradación por enzimas nucleótidas o aminas, lo que dificulta su manejo y almacenamiento en soluciones acuosas o en presencia de agua; por ello, su uso se limita a condiciones muy controladas y a formulaciones que eviten la exposición prolongada al medio acuoso. Las demás opciones son erróneas: la opción B es falsa porque las bases de Mannich no aumentan la lipofilia de manera excesiva, sino que pueden reducirla al introducir grupos polares; la opción C es incorrecta pues la estabilidad in vivo no es un problema, de hecho, la inestabilidad in vitro suele traducirse en una rápida degradación in vivo; y la opción D carece de fundamento, pues las bases de Mannich no tienden a formar redes cristalinas particularmente estables, sino que suelen presentar solubilidades variables y no presentan una tendencia a cristalizar de forma tan marcada.'),
  (210, 'El tetrazol presente en los antagonistas de los receptores de angiotensina II es un anillo heterocíclico con un átomo de nitrógeno que puede protonarse, generando un grupo carboxílico equivalente que confiere acidez; además, la presencia de cuatro nitrógenos y la conjugación con el anillo aromático aumenta la lipofilia del fármaco, favoreciendo su unión al receptor y su permeabilidad celular. El bifenilo, aunque lipofílico, no posee grupo ácido; el hidroximetilo es un grupo hidroxilo que no es ácido bajo las condiciones fisiológicas; y el n‑butilo es simplemente una cadena alquilada que aporta solubilidad en lípidos pero carece de acidez. Por tanto, solo el tetrazol cumple simultáneamente con las características de acidez y lipofilia requeridas.'),
  (211, 'Los fragmentos de betahidroxicarbonilo presentes en las antraciclinas actúan como sitios de coordinación que forman quelatos con el ion Fe³⁺, favoreciendo la generación de radicales hidroxilo a través de la reacción de Fenton; esta oxidación de especies reactivas de oxígeno produce daño oxidativo a la célula tumoral, lo que explica su actividad citotóxica. Las otras alternativas son inexactas: la opción A es falsa porque los antraciclinas no forman enlaces covalentes con el ADN, sino que se intercalan entre pares de bases; la B es errónea porque la interacción con la topoisomerasa I se basa en intercalación y no en enlaces de hidrógeno específicos con el fragmento de betahidroxicarbonilo; la C describe una hipótesis de conformación intramolecular que no se ha demostrado y no explica la actividad biológica de las antraciclinas.'),
  (212, 'El desplazamiento de un grupo hidroxilo del anillo catecol en los derivados de ariletanolamina reduce la capacidad de la molécula para ser reconocida por la catecol-O‑metiltransferasa (COMT), ya que la enzima requiere la presencia de ambos grupos OH en posiciones orto y meta para efectuar la metilación; al perder uno, la afinidad por COMT disminuye y la molécula se degrada más lentamente, lo que incrementa su estabilidad metabólica y prolonga su efecto farmacológico en los receptores adrenérgicos. Las opciones A y D son erróneas porque el cambio de posición no favorece la degradación por COMT ni por monoamino oxidasa (MAO), que actúan sobre el grupo amino y no dependen de la disposición de los OH. La alternativa B es incorrecta porque la pérdida de actividad no se debe a una menor analogía con el ligando endógeno, sino a la alteración de la interacción con la enzima de degradación, no con el receptor.'),
  (213, 'El catión metildiazonio se forma por la biotransformación de la procarbazina mediante la acción de la monoamino oxidasa hepática, que oxida el grupo amino de la procarbazina y genera el ion metildiazonio, el cual es el responsable de la actividad antitumoral, pues interacciona con el ADN de las células cancerosas; la ciclopfosfamida produce un metabolito alquilante N‑metil‑N‑(2‑fosfonil)‑3‑(1‑metil‑2‑azotil)‑1‑propanil, la mecloretamina se metaboliza a 4‑metil‑2‑ciclohexil‑1‑metil‑3‑azotil y el busulfán se convierte en 1‑metil‑2‑azotil, ninguno de los cuales forma un catión metildiazonio.'),
  (214, 'Selegilina es un inhibidor selectivo de la monoaminooxidasa B (MAO‑B) que, al bloquear la degradación de la dopamina en el sistema nervioso central, provoca un aumento de los niveles de esta catecolamina, lo que en el contexto de la enfermedad de Parkinson se asocia con la aparición de síntomas de “suicidio” (tendencia a la autolesión) cuando se administra en dosis elevadas o en combinación con otros inhibidores de MAO; por ello se clasifica como un inhibidor suicida. Lopinavir es un inhibidor de proteasa antiviral, captopril es un inhibidor de la enzima convertidora de angiotensina (ECA) y rivastigmina es un inhibidor de la colinesterasa; ninguno de estos compuestos actúa sobre la MAO ni presenta el perfil de riesgo de suicidio, razón por la cual las opciones A, B y D son erróneas.'),
  (215, 'La acetilación, que implica la transferencia de un grupo acetilo del acetil-CoA al sitio funcional del fármaco, no aumenta la polaridad del compuesto porque el grupo acetilo es relativamente lipofílico y no introduce grupos hidroxilo, carboxilo o sulfonato que puedan participar en enlaces de hidrógeno; por ello el metabolito resultante suele conservar una polaridad similar o incluso menor que la molécula original, a diferencia de la glucuronidación, la sulfato y la conjugación con glutatión, que añaden grupos cargados y altamente hidrofílicos que elevan la polaridad y favorecen la excreción renal. Las opciones A, C y D son incorrectas porque todas describen procesos de conjugación que sí generan metabolitos más hidrofílicos y, por tanto, de mayor polaridad.'),
  (216, 'El ácido barbitúrico se sintetiza típicamente a partir de un éster malónico (por ejemplo, acetato de etilo) que, tras una reacción de acilación con urea, forma el barbiturato mediante la sustitución de los grupos alquilo por los grupos N‑H de la urea; la reacción se lleva a cabo en presencia de un agente deshidratante o bajo condiciones de esterificación, produciendo el ciclo barbitúrico con la eliminación de agua y la formación de los enlaces C=N. Este mecanismo aprovecha la alta reactividad del éster malónico y la capacidad de la urea para aportar los dos grupos amida necesarios para cerrar el anillo, resultando en la generación de derivados barbitúricos cuando el éster malónico está adecuadamente sustituido. Las otras alternativas no conducen a la formación de un anillo barbitúrico: la opción A describe una reacción de hidrazina con un carbonílico enolizable, que daría un producto de hidrazona, no un barbiturato; la B involucra una 1,3‑diamina y carbonato de etilo, que típicamente produciría una diamida o un ciclo de 1,3‑dioxina, pero no un barbiturato; la C menciona acetilacetato de etilo, amoniaco y aldehídos aromáticos, que conduciría a productos de Mannich o de aldol, sin formar el anillo barbitúrico.'),
  (217, 'Las sulfonilureas reducen la glucosa al fijarse en el subunidante SUR1 de los canales de potasio dependientes de ATP (K_ATP) presentes en la membrana de las células beta pancreáticas; la unión provoca la inhibición de estos canales, lo que conduce a un aumento del potencial de membrana, apertura de los canales de calcio dependientes de potencial, entrada de Ca²⁺ y, finalmente, liberación de insulina, disminuyendo la glucosa plasmática. Los canales de calcio dependientes de potencial (opción A) son el efecto secundario de la inhibición de los K_ATP, no el sitio de acción primaria; los canales de sodio dependientes de potencial (opción B) no participan en la regulación de la secreción de insulina; y las bombas iónicas dependientes de ATP (opción C) se refieren a transportadores como la Na⁺/K⁺-ATPasa, que no son el blanco de las sulfonilureas.'),
  (218, 'La síntesis de péptidos mediante un aminoácido anclado a un soporte polimérico insoluble en el medio de reacción es la técnica de Merrifield, que permite la unión de los residuos de aminoácidos en cadena y la eliminación de los grupos protectores mediante pasos de acido y base, con la ventaja de que el sólido se puede filtrar y lavar entre cada etapa, evitando la contaminación de los productos y facilitando la purificación; la opción A (Hantzsch) describe la síntesis de compuestos heterocíclicos como la piridina, la B (Corey) se refiere a la síntesis de compuestos orgánicos mediante la reacción de Corey–House, y la D (Skraup) corresponde a la síntesis de anilina a partir de anilina y ácido sulfúrico, por lo que las tres alternativas no corresponden al método de síntesis de péptidos en soporte sólido.'),
  (219, 'El metabolito responsable de la hepatotoxicidad del paracetamol es el N‑acetil‑p‑cumaril‑oxim (NAPQI), un compuesto de tipo iminoquinona que se forma por la oxidación en el citocromo P450; su alta reactividad electrófila le permite covalentemente unirse a residuos de cisteína en proteínas hepáticas, provocando daño celular. El epóxido (A) es un intermediario de oxidación de compuestos aromáticos, pero no participa en el metabolismo del paracetamol; el catión aziridinio (B) es un grupo funcional que se forma en la reacción de formación de isocianatos, no en la vía del paracetamol; el isocianato (D) es un grupo funcional de amida de carbamato que tampoco se genera en este proceso. Todas las alternativas excepto la C describen especies químicas que no se obtienen ni no son relevantes para la toxicidad del paracetamol.'),
  (220, 'El parámetro de Hammett describe la influencia electrónica de los sustituyentes en una reacción o interacción, cuantificando su capacidad donadora o aceptora de electrones a través de constantes σ que se obtienen de estudios de sustitución en sistemas aromáticos; por ello la opción D es la única que refleja correctamente que el parámetro se relaciona con el efecto electrónico de los sustituyentes, pues las constantes σ se derivan de la diferencia de energía electrónica entre el compuesto sustituido y el compuesto base, y se utilizan para predecir la polaridad de los enlaces y la estabilidad de intermedios en reacciones de sustitución o adición. Las demás alternativas son incorrectas porque el parámetro de Hammett no mide la lipofilia (A), que se relaciona con la constante de distribución lipofílica (log P), ni el efecto estérico (B), que se evalúa con parámetros como el índice de sustitución de Taft (σ*), ni la fracción de fármaco que alcanza la diana (C), que depende de la farmacocinética y la biodisponibilidad, no de la electrónica de los sustituyentes.'),
  (221, 'El carbacol, al sustituir el grupo éster de la acetilcolina por un carbamato, adquiere una mayor estabilidad frente a la hidrólisis enzimática, ya que el enlace C–O del carbamato es menos susceptible a la acción de las colinesterasas; por ello la molécula presenta una vida media más prolongada y una menor degradación metabólica, lo que explica la estabilidad química y metabólica que se le atribuye; las demás alternativas son erróneas porque la opción A sugiere una mayor hidrolisis en medio ácido, lo cual es contrario al comportamiento de los carbamatos, la opción C postula una interacción π‑π que no está respaldada por la estructura del carbacol, y la opción D confunde la sustitución bioisostérica del metilo por un grupo amino con un efecto estérico que no aumenta la afinidad por la diana terapéutica.'),
  (222, 'La característica típica de los agentes alquilantes de la familia de las mostazas nitrogenadas es la presencia de un grupo que puede generar un catión aziridinio, ya que el mecanismo de acción de estos compuestos implica la formación de un anillo de aziridinio que, al ser un intermediario altamente reactivo, se enlaza covalentemente con bases nucleófilas en el ADN, causando quimioesteroquimiosíntesis y ruptura de enlaces; por tanto la opción B describe precisamente este rasgo funcional. Las demás alternativas son inadecuadas: la opción A se refiere a grupos de hidrógeno que pueden participar en enlaces de hidrógeno, pero no son característicos de las mostazas nitrogenadas, que dependen de la formación de catión aziridinio; la opción C menciona una cadena peptídica corta y cargada positivamente, lo cual es típico de peptídeos o poliaminas, no de los compuestos alquilantes; y la opción D habla de una estructura aromática plana y pobre en electrones, característica de compuestos aromáticos electron deficient, pero las mostazas nitrogenadas son compuestos de alquilación con grupos de aziridinio, no aromáticos.'),
  (223, 'El antídoto más eficaz contra los fosforados sarín y tabún es la hidroxilamina, que actúa como nucleófilo fuerte y reacciona con el fosfato carbamoilado de la acetilcolinesterasa (AChE) para desfosforilarla y restaurar la actividad enzimática; la hidroxilamina se une al fosfato, rompe la unión fosfato‑carbamoilada y libera la enzima sin requerir un proceso de reactivación controlado, lo que permite una recuperación rápida de la función neuromuscular. Las demás opciones presentan fallos: la B menciona la “hidrolización del residuo acetilado”, que no corresponde al mecanismo de acción de los fosforados, que dejan una carbamoilación; la C propone hidroxicloroquina, un compuesto antimaláricos con baja nucleofilia y sin capacidad de desfosforilación; la D habla de hidrazina, que aunque nucleófila, no es el agente clínicamente usado y su reacción con el fosfato no es tan eficiente ni rápida como la de la hidroxilamina.'),
  (224, 'La anfotericina B es un polieno, ya que su estructura contiene una cadena de doble enlace conjugado que le confiere la característica de este grupo de compuestos; actúa ligándose a ergosterol en la membrana fúngica y creando poros que alteran la permeabilidad celular, una acción típica de los polienos, mientras que los triazoles (opción B) y las candinas (C) son inhibidores de la síntesis de ergosterol, y las sulfamidas (D) son antibacterianos que antagonizan la dihidrofolato reductasa, por lo que no pertenecen al mismo mecanismo ni clase farmacológica.'),
  (225, 'Los hongos Mucorales pertenecen al filo Zygomycota y son etiológicos de la mucormicosis, una infección invasiva que suele presentarse en pacientes inmunocomprometidos o con diabetes mal controlada; su clínica típica incluye sinusitis, rino‑órbitocerebral, neumonía, lesiones cutáneas y, en casos graves, diseminación a órganos distantes, por lo que la opción C resume fielmente el espectro de localizaciones que caracterizan a esta enfermedad, reflejando la capacidad de estos organismos de invadir tejidos blandos y vasculares. En contraste, la opción A es errónea porque los Mucorales son inherentemente resistentes a los triazoles, incluido el voriconazol, y su tratamiento se basa en agentes como el anfotericina B o el posaconazol; la opción B es incorrecta porque la detección de β‑1,3‑glucano es útil para identificar hongos de la clase de los Aspergillus y los hongos de la familia de los Candida, pero los Mucorales carecen de esta molécula en su pared celular, por lo que el ensayo no es diagnóstico; la opción D también es falsa, ya que los Mucorales no muestran afinidad por tejidos queratinizados, sino que prefieren tejidos con alta disponibilidad de hierro y ambientes ácidos, como los tejidos mucosos y pulmonares.'),
  (226, 'La resistencia a las quinolonas se debe principalmente a mutaciones en los genes que codifican la ADN girasa (gyrA y gyrB) y la topoisomerasa IV (parC y parE), alterando los sitios de unión del fármaco y reduciendo su afinidad; por tanto la opción A describe el mecanismo fisiológico real. La opción B es incorrecta porque las quinolonas no son modificadas por acetiltransferasas, un mecanismo típico de resistencia a antibióticos como la tetraciclina. La C es inexacta, pues las β‑lactamasas hidrolizan β‑lactámicos y no afectan a las quinolonas. La D se refiere a la resistencia a macrólidos y no tiene relación con la acción de las quinolonas, por lo que también es errónea.'),
  (227, 'La leucocidina Panton‑Valentine (PVL) es una proteína exotoxina que actúa como citotoxina, formando poros en membranas celulares de leucocitos y provocando su lisis; por ello se asocia con cuadros cutáneos graves, como abscesos y necrosis de piel y tejidos blandos, y se detecta con frecuencia en cepas de Staphylococcus aureus resistentes a meticilina que se originan en infecciones comunitarias, lo que explica la opción A y la opción B. En contraste, la PVL no se ha relacionado con intoxicaciones alimentarias, ya que su mecanismo de acción se limita a la lisis de leucocitos y no a la producción de toxinas que causen síntomas gastrointestinales; por lo tanto la opción D es la que presenta información errónea. Las demás opciones son correctas porque describen aspectos clínicos y microbiológicos bien establecidos de la PVL.'),
  (228, 'Staphylococcus saprophyticus es una especie de estafilococo coagulasa‑negativo que constituye la segunda causa bacteriana de infecciones del tracto urinario en mujeres jóvenes, debido a su afinidad por la mucosa genital y su capacidad de adherirse a las células de la vejiga; por ello la opción A describe adecuadamente su patogenia clínica. La fosfomicina, aunque activa contra muchos estafilococos, no es la primera línea de tratamiento para esta bacteria y su sensibilidad no se considera característica distintiva, lo que hace que la opción B sea imprecisa. La novobiocina es un antibiótico que actúa sobre la DNA gyrase y su uso se reserva principalmente para el tratamiento de infecciones por estafilococos coagulasa‑positivos, por lo que la afirmación C es incorrecta. Finalmente, S. saprophyticus es coagulasa‑negativo, por lo que la opción D describe una característica de otro grupo de estafilococos y resulta errónea.'),
  (229, 'La respuesta es la opción A, Pasteurella multocida, porque es un bacilo gram‑negativo que presenta oxidasa positiva, no se cultiva sobre agar MacConkey y es el patógeno más frecuente en heridas tras mordeduras de animales domésticos, especialmente perros y gatos; su crecimiento se favorece en medios con sangre y se inhibe por la presencia de coliformes en MacConkey. La opción B, Francisella tularensis, es un bacilo gram‑negativo oxidasa negativa que sí crece en agar MacConkey y se asocia con la enfermedad de tularemia, no con heridas por mordedura; la opción C, Neisseria gonorrhoeae, es un diplococo gram‑negativo oxidasa positiva que se cultiva en medios específicos como chocolate agar, pero tampoco se encuentra en MacConkey y no es típico de mordeduras; la opción D, Enterobacter cloacae, es un bacilo gram‑negativo oxidasa negativa que sí crece en agar MacConkey y se relaciona con infecciones nosocomiales, no con heridas de mordedura.'),
  (230, 'La opción D es la que presenta la afirmación errónea: la fiebre de Pontiac se caracteriza por fiebre, malestar general y síntomas respiratorios leves, pero no se asocia con enfermedad pulmonar de base; en cambio, la enfermedad de los legionarios implica neumonía grave con infiltrados pulmonares y puede progresar a insuficiencia respiratoria. La afirmación de que la fiebre de Pontiac se asocia con enfermedad pulmonar de base confunde dos entidades clínicas distintas, pues la fiebre de Pontiac es una forma leve de infección que no produce daño pulmonar significativo. En contraste, la opción A es correcta porque las infecciones por Legionella pueden ser asintomáticas con frecuencia, especialmente en personas inmunocompetentes. La opción B es precisa al describir las dos manifestaciones clínicas: fiebre de Pontiac y enfermedad de los legionarios. La opción C también es válida, ya que el tratamiento de elección para la infección por Legionella es con macrólidos (por ejemplo, azitromicina) o con fluoroquinolonas (por ejemplo, ciprofloxacino), que penetran bien en los tejidos y en los macrófagos donde reside el bacilo.'),
  (231, 'El grupo HACEK comprende bacterias gramnegativas de cadena corta que son agentes habituales de endocarditis infecciosa: Haemophilus, Aggregatibacter (antes Actinobacillus), Cardiobacterium, Eikenella y Kingella; por tanto, la única bacteria de la lista que no forma parte de este grupo es Achromobacter xylosoxidans, que pertenece a la familia Alcaligenaceae y se asocia a infecciones respiratorias y urinarias, no a endocarditis; las demás opciones sí pertenecen a HACEK, ya que Cardiobacterium hominis, Kingella kingae y Eikenella corrodens son especies reconocidas dentro de este conjunto de patógenos.'),
  (232, 'La identificación presuntiva de Streptococcus pneumoniae se basa en su patrón de hemólisis, sensibilidad a la optoquina y la capacidad de solubilizar bilis; la opción C reúne los tres criterios característicos: la hemólisis alfa (intermedia) en agar sangre, la sensibilidad a la optoquina (un antibiótico de la familia de las quinolonas que S. pneumoniae suele tolerar) y la prueba de solubilidad en bilis positiva, que indica la presencia de la enzima bilis soluble típica de este organismo; los demás enunciados fallan porque presentan combinaciones incompatibles con la biología de S. pneumoniae: la opción A incluye sensibilidad a la optoquina pero la prueba de solubilidad en bilis positiva es correcta, sin embargo la hemólisis alfa es la esperada, no la beta; la opción B combina hemólisis beta (inusual) con resistencia a la optoquina y solubilidad en bilis negativa, contradiciendo la fisiología del patógeno; la opción D presenta hemólisis alfa y resistencia a la optoquina, pero la resistencia a la optoquina no es característica de S. pneumoniae, por lo que todas las alternativas excepto la C son incorrectas.'),
  (233, 'Avibactam es un inhibidor de β‑lactamasas que forma un complejo covalente con la serina activa de la enzima, bloqueando su actividad; su espectro incluye la mayoría de las β‑lactamasas de clase A, C y D, y también las BLEE, pero no actúa sobre las carbapenemasas que dependen de un metal (metaloβ‑lactamasas), ya que su mecanismo de inhibición requiere la presencia de la serina activa y no puede interactuar con el sitio metal‑ligado; por ello la opción C es la única que no se inhibe. Las opciones A, B y D son incorrectas porque avibactam sí inhibe las BLEE, las AmpC y las OXA‑48, respectivamente, gracias a su capacidad de formar el complejo covalente con la serina de estas enzimas.'),
  (234, 'La opción D es la única que concuerda con la biología del agente, la patología y el vector; Rickettsia conorii pertenece al grupo de las rickettsias de la familia Rickettsiaceae, causa la fiebre botonosa mediterránea y se transmite por garrapatas del género Rhipicephalus (principalmente Rhipicephalus sanguineus), que son vectores típicos de esta enfermedad en la región mediterránea, lo que explica la asociación clínica y epidemiológica; las demás alternativas presentan errores: la opción A confunde el vector, ya que Coxiella burnetii (fiebre Q) se transmite por inhalación de material contaminado o por vectores de la familia Ixodidae, pero no por Ixodes spp. en la práctica clínica; la opción B presenta un desajuste entre el agente y el vector, pues Bartonella bacilliformis (fiebre de Oroya) se transmite por mosquitos del género Simulium, no por Hyalomma spp.; y la opción C asocia incorrectamente a Borrelia burgdorferi (enfermedad de Lyme) con Aedes spp., mientras que el vector real es la garrapata Ixodes scapularis, no un mosquito.'),
  (235, 'La peste bubónica es causada por Yersinia pestis, no por Yersinia enterocolitica; la transmisión humana se produce principalmente a través de la picadura de pulgas del género Xenopsylla que infestan a las ratas, por lo que la opción B describe el mecanismo epidemiológico correcto. El periodo de incubación de la peste bubónica suele oscilar entre 2 y 6 días, por lo que la afirmación de 30 a 60 días (opción C) es errónea; la opción A es incorrecta porque identifica al microorganismo equivocado; la opción D es falsa porque el tratamiento estándar en todos los pacientes, no solo en inmunodeprimidos, incluye antibióticos como ciprofloxacino, gentamicina o estreptomicina, y la vancomicina no es el fármaco de elección.'),
  (236, 'La afirmación A es incorrecta porque el diagnóstico de tularemia no se fundamenta exclusivamente en el cultivo y el frotis de lesiones; aunque el cultivo de muestras de lesiones ulcerativas o de sangre puede confirmarlo, la práctica clínica habitual recurre a pruebas serológicas (hemaglutinación, ELISA, inmunofluorescencia) y, en casos de sospecha alta, a PCR, ya que el cultivo es laborioso y de baja sensibilidad en muestras de lesiones; por tanto, el diagnóstico se basa en un conjunto de pruebas, no únicamente en cultivo y frotis. Las opciones B y C son correctas: los lagomorfos y roedores son reservorios naturales de Francisella tularensis, que es un cocobacilo gramnegativo; la opción D también es correcta, pues la estreptomicina y la gentamicina son antibióticos de primera línea para la tularemia grave, con la excepción de la forma meningitis, donde se prefiere la ceftriaxona o la cefotaxima.'),
  (237, 'La afirmación B es la única que resulta incorrecta porque el régimen de tratamiento de la endocarditis por Coxiella burnetii exige una combinación de doxiciclina (200 mg/día) con rifampicina (600 mg/día) durante al menos 14 semanas, no solo 14 días; la duración prolongada es necesaria para lograr la erradicación bacteriana y evitar recaídas, mientras que la doxiciclina sola no es suficiente. En cambio, la opción A describe adecuadamente la clínica de la fiebre Q, que puede manifestarse como una enfermedad febril autolimitada, neumonía, endocarditis o hepatitis. La opción C también es correcta, pues la transmisión ocurre principalmente por inhalación de aerosoles contaminados, y, aunque menos frecuente, la ingestión de leche no pasteurizada puede ser fuente de infección. Finalmente, la opción D es válida, ya que las técnicas de amplificación de ácidos nucleicos (PCR) se emplean con éxito en muestras clínicas como sangre, válvulas cardíacas o líquido articular para el diagnóstico de la fiebre Q aguda.'),
  (238, 'La colistina, como polimixina, actúa sobre la membrana citoplasmática de bacterias gram‑negativas mediante la interacción con lípidos fosfatídicos, lo que provoca permeabilización y muerte celular; la resistencia plasmídica se ha documentado en la enzima MCR‑1 que fosforilación del lipopolisacárido, reduciendo la afinidad de la polimixina, por lo que la opción D refleja el mecanismo actual de resistencia plasmídica; las demás alternativas son erróneas: la opción A es falsa porque existen formulaciones inhaladas y orales (en investigación) además de las intravenosas y tópicas; la opción B es incorrecta porque las polimixinas no son activas frente a especies de Proteus, que son gram‑positivas o gram‑negativas con resistencia inherente; la opción C es inexacta porque los efectos adversos más frecuentes de la colistina son la nefrotoxicidad y la neurotoxicidad reversible, no la hepatotoxicidad, y su relación con la dosis es bien documentada, pero la descripción de “irreversible” es errónea.'),
  (239, 'La clindamicina no se emplea para tratar la infección por Clostridioides difficile ni sus recurrencias porque, a diferencia de la fidaxomicina, la vancomicina oral y el bezlotoxumab, su espectro incluye bacterias gram‑positivas y anaerobias, pero su uso en este contexto aumenta la probabilidad de favorecer la proliferación de C. difficile al alterar la microbiota intestinal; además, la clindamicina es un fármaco que se asocia con un alto riesgo de colitis pseudomembranosa, por lo que se evita intencionadamente en este cuadro. En cambio, la fidaxomicina actúa con alta concentración en el colon y con mínima alteración de la flora normal, la vancomicina oral se concentra en el lumen gastrointestinal y es la primera línea de tratamiento, y el bezlotoxumab, un anticuerpo monoclonal, bloquea la toxina B de C. difficile y reduce la recurrencia. Por tanto, la opción C es la única que no se utiliza, mientras que las opciones A, B y D sí se emplean en la práctica clínica.'),
  (240, 'El medio de cultivo habitual para la detección de Bordetella pertussis, agente causal de la tos ferina, es el medio de Bordet‑Gengou, formulado con agar de caldo de carne, calcio y fosfato, que favorece el crecimiento de esta bacteria gram‑negativa exigente; su uso se justifica porque permite la formación de colonias típicas y facilita la identificación por tinción de Gram y pruebas bioquímicas específicas. El medio de Löwenstein‑Jensen se emplea para Mycobacterium tuberculosis, el BCYE (Brain‑Heart Infusion + Calcio + Yeast Extract) se reserva para Haemophilus influenzae y el Thayer‑Martin se utiliza para Neisseria meningitidis; por tanto, las opciones B, C y D corresponden a cultivos de microorganismos distintos y no son adecuados para la tos ferina.'),
  (241, 'Haemophilus influenzae es un bacilo gramnegativo de forma coccobacilar, por lo que la afirmación A es verídica; su morfología se describe como cocobacilo y su tinción de Gram muestra coloración negativa. En cuanto a su cultivo, no es capaz de crecer en agar MacConkey, ya que este medio contiene cristal violeta y bile que inhiben a los microrganismos no enterobacterias, y H. influenzae requiere de factores de crecimiento como sustrato de sangre o agar chocolate; por lo tanto la opción B es la que presenta la afirmación incorrecta. La existencia de seis serotipos capsulares (a, b, c, d, e, f) es bien documentada y constituye la base de la vacunación, lo que hace que la opción C sea correcta. Finalmente, la resistencia más frecuente a las penicilinas en H. influenzae se debe a la producción de β-lactamasas (penicilinas de baja actividad), lo que confirma la opción D. Así, la única afirmación errónea es la que indica crecimiento en agar MacConkey.'),
  (242, 'La distomatosis hepática, causada por la larva de *Echinococcus granulosus*, se presenta con fiebre y dolor en el hipocondrio derecho cuando la cística se localiza en el hígado; el consumo de verduras crudas en zonas endémicas como el Altiplano boliviano favorece la ingestión de huevos contaminados, lo que explica el cuadro clínico descrito. La hidatidosis alveolar (A) es una enfermedad pulmonar crónica que suele manifestarse con síntomas respiratorios y no con dolor hepático; la linfangitis aguda (C) se caracteriza por inflamación de los vasos linfáticos con fiebre, pero no se asocia con consumo de verduras ni con el dolor localizado en el hipocondrio derecho; la clonorchiasis (D) provoca ictericia y dolor abdominal, pero su transmisión se da por consumo de pescado crudo, no de verduras, y el cuadro de fiebre aguda no es típico.'),
  (243, 'El enunciado C es el que resulta incorrecto porque la detección de huevos de Schistosoma en heces es poco sensible en la fase aguda del síndrome de Katayama; en esta etapa la carga parasitaria es baja y los huevos aún no se excretan en cantidades detectables, por lo que se recurre a pruebas serológicas o a la búsqueda de antígenos en sangre o orina, mientras que la fase crónica sí permite la identificación de huevos con mayor frecuencia. En cambio, la opción A es verdadera pues el síndrome de Katayama se produce tras la infección por Schistosoma spp.; la opción B describe adecuadamente las manifestaciones clínicas típicas, incluyendo fiebre, erupción cutánea, hepatosplenomegalia, broncoespasmo y eosinofilia; y la opción D indica el tratamiento estándar, que combina praziquantel para erradicar el parásito y corticoides para controlar la inflamación y la respuesta inmunitaria que causa los síntomas.'),
  (244, 'La opción D corresponde a Giardia lamblia, un protozoo intestinal que se transmite por agua y alimentos contaminados y que presenta una alta prevalencia en niños, especialmente en áreas con saneamiento insuficiente, y se clasifica como enfermedad de declaración obligatoria en la normativa sanitaria española; su capacidad de producir diarrea crónica, desnutrición y retraso en el desarrollo lo convierte en un foco de preocupación epidemiológica. En cambio, Entamoeba coli (A) es un parásito asintomático y no se considera de relevancia clínica ni de declaración obligatoria; Trichinella spiralis (B) provoca triquinosis, enfermedad de transmisión zoonótica, pero su incidencia es baja y no se declara obligatoria; Echinococcus granulosus (C) causa cisticercosis, una enfermedad de declaración obligatoria, pero su prevalencia es mucho menor en la población infantil comparada con Giardia, por lo que no cumple el criterio de alta prevalencia infantil.'),
  (245, 'El planteamiento matemático de Heckel se emplea para caracterizar la compresión de polvos farmacéuticos, permitiendo evaluar la densidad y la deformación de los materiales sólidos a medida que se aplica presión, lo que facilita la predicción de la resistencia y la cohesión del comprimido; las otras opciones describen conceptos distintos: la opción B se refiere a la farmacocinética de fármacos poco solubles, la C a la viscosidad de semisólidos, y la D a la cinética de disolución, ninguno de los cuales está relacionado con la ecuación de Heckel.'),
  (246, 'La floculación controlada de suspensiones se logra mediante la adición de electrolitos que reducen la magnitud del potencial Z, disminuyendo la repulsión electrostática entre las partículas y favoreciendo su acercamiento y unión; por tanto la opción B describe correctamente el mecanismo farmacológico de ajuste del potencial Z para controlar la floculación. Las demás alternativas son erróneas: la A confunde quelantes con floculantes y niega la relación con el potencial Z; la C atribuye el control al tamaño de partícula cuando el potencial Z es el factor determinante; y la D mezcla la viscosidad con el potencial Z, aunque los agentes viscosizantes no modifican directamente el potencial Z.'),
  (247, 'El ensayo de resistencia a la fractura no es obligatorio en la Farmacopea Española; se menciona como uno de los posibles ensayos para verificar la resistencia mecánica de los comprimidos, lo que permite a los fabricantes elegirlo según las necesidades de calidad y control de procesos, sin que la normativa lo exija como requisito de lote final. Las alternativas A y C son erróneas porque asumen una obligatoriedad o una condición específica de recubrimiento que no se establece en la Farmacopea. La opción D, aunque menciona que es recomendable, la describe como un ensayo oficial, lo cual no corresponde al texto normativo que lo presenta como opcional y no como ensayo oficial.'),
  (248, 'El método de Scherer es el proceso industrial estándar para la fabricación de cápsulas gelatinosas blandas, ya que emplea la técnica de “gelificación por enfriamiento” en la que una solución de gelatina se extruye en un molde con un núcleo de aceite, se solidifica y se recubre con una capa de gelatina, garantizando la integridad y la flexibilidad de la cápsula; las demás opciones corresponden a métodos de medición de propiedades físicas de polvos (Higuchi, Hausner) o a técnicas de formulación de comprimidos (Atkinson), por lo que no se aplican a la producción de cápsulas blandas.'),
  (249, 'El ensayo de endotoxinas bacterianas, conocido como prueba de Limulus o prueba de LAL, se emplea específicamente para detectar la presencia de pirógenos, es decir, endotoxinas lipopolisacáridos liberados por bacterias gram‑negativas, en preparados farmacéuticos y dispositivos médicos; su sensibilidad permite identificar contaminaciones que, aunque no sean bacterias vivas, pueden provocar fiebre, shock y otras reacciones inflamatorias graves en el paciente, por lo que su uso es indispensable en la evaluación de la seguridad de los productos. Las opciones A y C son erróneas porque el ensayo no evalúa la toxicidad de bacterias anaerobias ni la presencia de bacterias Gram‑positivas, ya que estas no liberan endotoxinas; la opción D es inexacta porque el ensayo no cuantifica la toxicidad de una especie bacteriana específica, sino que mide la actividad endotoxínica total, independientemente de la especie.'),
  (250, 'El diámetro equivalente de Stokes se define como el diámetro de una esfera de densidad idéntica a la de la partícula que sedimenta a la misma velocidad terminal bajo la misma viscosidad y gravedad; por ello la opción A es la que describe correctamente el concepto, pues la velocidad terminal depende únicamente de la masa (o densidad) y el área superficial de la partícula, y el diámetro equivalente permite comparar partículas de forma irregular con una esfera ideal. Las demás alternativas son incorrectas: la opción B confunde el diámetro con la superficie, lo cual no determina la velocidad de sedimentación; la C asume que el volumen es el criterio, pero el volumen no garantiza la misma velocidad porque la densidad también interviene; y la D relaciona el diámetro con la resistencia eléctrica en un contador Coulter, una medida que se basa en el cambio de conductividad y no en la dinámica de sedimentación.'),
  (251, 'En el proceso de desecación, la dirección de la transferencia de vapor de agua está determinada por el gradiente de presión de vapor entre el sólido y el aire; cuando la presión de vapor del agua en el sólido supera la del aire, el vapor tiende a difundirse hacia la fase gaseosa hasta que se igualen las presiones, por lo que la opción A describe correctamente el fenómeno de desecación, ya que el sólido pierde humedad y el aire se humedece, manteniendo el equilibrio cuando las presiones son iguales; la opción B es errónea porque implica una transferencia opuesta a la dirección del gradiente de presión, lo que ocurriría solo si la presión de vapor del aire fuera mayor; la opción C es incorrecta porque asume que no habrá transferencia cuando las presiones son diferentes, lo cual contradice la ley de difusión; la opción D es falsa porque la transferencia de vapor del sólido al aire no depende de que la humedad relativa sea 100 %, sino del gradiente de presión de vapor, y la humedad relativa del 100 % implicaría que el aire ya está saturado, pero la transferencia seguiría ocurriendo hasta que se igualen las presiones.'),
  (252, 'La percepción de la profundidad a partir de las disparidades retinianas generadas por la separación horizontal de los ojos se conoce como estereopsis, ya que implica la fusión de dos imágenes ligeramente diferentes para crear una única percepción tridimensional; la amaurosis se refiere a la pérdida total de visión, el estrabismo es la desviación de los globos oculares que impide la alineación correcta de las imágenes y la ambliopía es una deficiencia visual no corregible con lentes, por lo que las opciones B, C y D describen condiciones distintas a la estereopsis.'),
  (253, 'El efecto que describe la unión de oxígeno a la hemoglobina, con la consecuente liberación de dióxido de carbono en la sangre, es el efecto Haldane, que se basa en la alteración de la afinidad de la hemoglobina por CO₂ cuando se incrementa la saturación de O₂; el oxígeno favorece la liberación de CO₂ de la hemoglobina y su transporte al pulmón, mientras que el efecto Bohr explica la liberación de O₂ en tejidos con pH bajo y CO₂ alto, pero no la redistribución de CO₂; el efecto Doppler se relaciona con la velocidad de flujo sanguíneo y la frecuencia de ondas, y el efecto Venturi describe la reducción de presión con aumento de velocidad en un conducto, ninguno de los cuales explica la relación entre O₂ y CO₂ en la hemoglobina.'),
  (254, 'La respuesta es la opción A porque las máculas del utrículo y del sáculo, situadas en el laberinto membranoso, están revestidas por células sensoriales con estereocilios que se apoyan sobre una placa de otoliti, permitiendo que la gravedad y los movimientos lineales de la cabeza se conviertan en señales mecánicas que se transmiten al sistema vestibular; los conductos cocleares (B) pertenecen al oído interno pero son responsables de la audición, no de la orientación; los conductos endolinfáticos (C) son conductos que transportan el líquido endolinfático y no funcionan como órganos sensoriales de la gravedad; los órganos tendinosos de Golgi (D) son sensores de tensión en músculos y tendones, no forman parte del aparato vestibular.'),
  (255, 'La colecistoquinina (CCK) es secretada por las células I (o células de I) que se localizan en la mucosa del duodeno y del yeyuno, donde responden a la presencia de ácidos grasos y péptidos; esta secreción estimula la contracción de la vesícula biliar y la liberación de enzimas pancreáticas, función que no se lleva a cabo en las células G del estómago, que liberan gastrina, ni en las células S del duodeno, que producen secretina, ni en las células K del intestino grueso, que secretan histamina y hormonas de tipo enteroendocrino. Por tanto, la opción C es la única que describe el sitio fisiológico correcto de la secreción de CCK.'),
  (256, 'La repolarización ventricular se refleja en la onda T del ECG, ya que esta deflecta positiva (en la derivación estándar) tras la despolarización que produce el complejo QRS; la onda T representa la recuperación de los potenciales de membrana de las fibras miocárdicas ventriculares, y su duración y morfología dependen de la conductividad y el equilibrio iónico de los iones K⁺ y Ca²⁺. El complejo QRS, por otro lado, representa la despolarización de los ventrículos; el intervalo PR corresponde a la conducción atrioventricular y la fase de conducción del nodo sinusal y AV; el intervalo QT abarca tanto la despolarización como la repolarización ventricular, pero no identifica exclusivamente la fase de repolarización.'),
  (257, 'El desplazamiento hacia la derecha de la curva de disociación de oxígeno-hemoglobina se produce cuando la afinidad de la hemoglobina por el oxígeno disminuye, favoreciendo la liberación de O₂ a los tejidos; esto ocurre con aumento de 2,3‑DPG, incremento de pCO₂ y acidosis (disminución del pH), ya que estos factores favorecen la conformación relajada (R) de la hemoglobina. En cambio, la disminución de la temperatura favorece la conformación establecida (S) y, por lo tanto, aumenta la afinidad de la hemoglobina por el oxígeno, desplazando la curva hacia la izquierda. Las opciones A, C y D son fenómenos que sí están asociados al desplazamiento derecho, mientras que la opción B representa el único caso contrario.'),
  (258, 'La gastrina es una hormona peptídica producida por las células G del antro gástrico y, en menor medida, por las células K del duodeno y yeyuno; sin embargo, la opción C confunde la clasificación de las células productoras de gastrina con la de las células que secretan peptidogénos y enzimas digestivas, pues las células K son responsables de la secreción de histamina y no de gastrina, y la gastrina se origina principalmente en las células G del antro, no en las células K; por tanto, la afirmación es incorrecta. En contraste, la opción A es válida porque la gastrina estimula directamente a las células parietales a secretar ácido clorhídrico mediante la vía Gq/PLC y la liberación de calcio intracelular; la opción B también es correcta, pues la gastrina activa las células principales a través de receptores Gq, aumentando la producción de pepsinógeno; y la opción D es cierta, ya que la gastrina contribuye al mantenimiento de la mucosa gástrica al promover la síntesis de mucina y la reparación de la epitelio gástrico. Las opciones A, B y D, por tanto, reflejan funciones fisiológicas bien establecidas de la gastrina, mientras que la opción C presenta una confusión anatómica y funcional que la hace incorrecta.'),
  (259, 'La eficiencia mecánica del corazón, definida como el cociente entre el trabajo mecánico (potencia desarrollada) y el gasto de energía química (consumo de oxígeno), se sitúa típicamente entre el 20 % y el 25 % en individuos sanos; este rango refleja la proporción de la energía oxidativa que se convierte en trabajo útil, el resto consumiéndose en procesos de mantenimiento celular, transporte de iones y producción de calor. La opción B se ajusta a este valor fisiológico, mientras que la alternativa A (5‑10 %) subestima en gran medida la eficiencia real, pues los estudios de calorimetría cardíaca muestran valores superiores al 15 %. La opción C (45‑50 %) sobreestima la eficiencia, pues implicaría que la mitad de la energía oxidada se transformase en trabajo, algo incompatible con la evidencia de que la mayor parte del gasto energético se destina a la homeostasis intracelular. Finalmente, la alternativa D (>60 %) es imposible bajo condiciones fisiológicas normales, ya que requeriría una conversión de energía casi perfecta, algo que no se observa en el corazón humano.'),
  (260, 'La opción A es la que no pertenece al sistema nervioso central, porque las células de Schwann son glía periférica que envuelven los axones fuera del SNC y forman la vaina de mielina en el sistema nervioso periférico; en contraste, los astrocitos, la microglía y los oligodendrocitos son tipos de glía que se encuentran exclusivamente en el SNC y cumplen funciones de soporte, regulación del microambiente y mielinización de los axones cerebrales. Las opciones B, C y D son incorrectas en la pregunta porque, aunque todas son células de sostén, cada una sí forma parte del SNC: los astrocitos participan en la barrera hematoencefálica y el metabolismo neuronal, la microglía actúa como macrófago residente del cerebro y los oligodendrocitos generan la mielina de los axones intracraneales.'),
  (261, 'El óxido nítrico es el neurotransmisor que, al activarse el receptor postsináptico, induce de forma casi instantánea la síntesis de NO a través de la enzima óxido nítrico sintasa (NOS) en la célula postsináptica; el NO, siendo un gas difusible, atraviesa la membrana y se difunde libremente fuera del terminal presináptico durante segundos, sin requerir vesículas para su liberación, y actúa sobre las células vecinas, principalmente vasodilatando o modulando la transmisión sinérgica; el GABA se libera vesicularmente y su acción es inhibidora, la acetilcolina se sintetiza en la célula postsináptica pero se libera vesicularmente en el terminal presináptico y el NO es el único que se difunde directamente, mientras que la dopamina también se libera vesicularmente y su síntesis no depende de la activación postsináptica inmediata.'),
  (262, 'La secreción de H⁺ y la formación de HCO₃⁻ en el túbulo colector cortical se realizan por las células intercaladas, que poseen una gran cantidad de ATP‑ase de H⁺ en la membrana apical y transportadores de bicarbonato en la basolateral, permitiendo la excreción de ácido y la recaptación de bicarbonato; las demás opciones describen tipos celulares que no participan en esa función: las células principales se encargan principalmente de la reabsorción de Na⁺ y la secreción de K⁺, las yuxtaglomerulares forman la hormona renina y las células corticales no son una clasificación reconocida en el colector, por lo que las alternativas A, B y C son incorrectas.'),
  (263, 'La PTH aumenta la concentración sérica de calcio y fosfato mediante la estimulación de la resorción ósea, la reabsorción renal de calcio y la excreción de fosfato; por lo tanto, la opción que describe la acción sobre el hueso es la C, pues la hormona promueve la liberación de ambos minerales a partir de la matriz ósea. Las alternativas A y B son incorrectas porque la PTH favorece la reabsorción de calcio y la excreción de fosfato, no su inhibición; la opción D es errónea porque la PTH no inhibe, sino que potencia la resorción ósea.'),
  (264, 'Las glándulas que se encuentran en la mucosa del duodeno, particularmente en la zona entre el píloro gástrico y la ampolla de Vater, se denominan glándulas de Brunner; su función principal es secretar una mucosa rica en bicarbonato y mucina que neutraliza el ácido del estómago y protege la mucosa intestinal, característica que las distingue de las glándulas de Lieberkühn (que se localizan en el intestino delgado y secretan enzimas digestivas), de las glándulas de Paneth (ubicadas en la base de los criptos y con función bactericida), y de las glándulas oxínticas (que se encuentran en el estómago y secretan ácido clorhídrico).'),
  (265, 'La hormona que activa las neuronas AGRP‑NPY y estimula la ingesta es la grelina, porque esta hormona peptídica, secretada por el estómago cuando el vaciamiento gástrico es bajo, atraviesa la barrera hematoencefálica y se une a receptores GHSR‑1a en el núcleo arqueado del hipotálamo, donde potencia la liberación de NPY y AGRP, neurotransmisores orexígenos que aumentan el apetito; la leptina y la insulina, en cambio, son hormonas satípticas que inhiben la actividad de las neuronas AGRP‑NPY, mientras que la colecistoquinina actúa principalmente en el tracto gastrointestinal y en el nervio vago para reducir la ingesta, no estimulándola.'),
  (266, 'La secreción de ADH se estimula principalmente por la osmolalidad plasmática y el volumen sanguíneo; sin embargo, la estimulación también puede producirse por estímulos neurogénicos que reflejan estados de malestar, entre los que se incluye la náusea, la cual activa vías de retroalimentación que aumentan la liberación de ADH para conservar agua y mantener la presión arterial; el consumo de alcohol, por el contrario, inhibe la liberación de ADH y provoca diuresis, por lo que la opción A es errónea; el descenso de la osmolaridad plasmática (opción C) y el aumento del volumen plasmático (opción D) son factores que reducen la secreción de ADH, por lo que también resultan incorrectas.'),
  (267, 'La célula más madura de la serie granulocítica es el metamielocito, pues en la maduración de los granulocitos la progresión es de mieloblasto → promielocito → metamielocito → mielocito, y el metamielocito presenta un núcleo más segmentado y granulación más desarrollada que el promielocito, pero todavía no alcanza la completa madurez funcional del mielocito; el mielocito es la etapa terminal, por lo que la opción B describe la etapa intermedia más madura que el promielocito, el mieloblasto y el mielocito, que son más inmaduras. Las opciones A, C y D se refieren a etapas anteriores de la maduración, por lo que no cumplen con la condición de ser la más madura.'),
  (268, 'El hallazgo prioritario en un frotis de un paciente con deterioro neurológico y trombocitopenia severa es la presencia de esquisocitos, ya que estos eritrocitos deformados con bordes afilados son indicativos de microangiopatía hemolítica, la cual es la causa más frecuente de hemólisis intravascular asociada a trombocitopenia y puede desencadenar síntomas neurológicos por microembolia o isquemia cerebral; la identificación de esquisocitos permite diferenciar rápidamente la microangiopatía de otras causas de hemólisis y orientar el manejo urgente. Los esferocitos (A) se asocian a defectos de la membrana eritrocítica como la anemia hemolítica hereditaria, no a la trombocitopenia aguda; los acantocitos (C) y los equinocitos (D) son formas de eritrocitos con proyecciones anómalas que se observan en enfermedades crónicas o en trastornos de la síntesis de hemoglobina, y no son el hallazgo de primera línea en este contexto clínico.'),
  (269, 'El test de Coombs directo detecta anticuerpos o complementos adheridos a la superficie eritrocitaria; por ello es la herramienta diagnóstica esencial para confirmar la anemia hemolítica adquirida de origen inmune, donde los glóbulos rojos son atacados por el sistema inmunitario y el resultado positivo confirma la presencia de inmunoglobulinas o complementos en la membrana eritrocítica, lo que permite diferenciarla de las hemolíticas no inmunes y orientar el tratamiento inmunosupresor; la opción A es incorrecta porque la anemia hemolítica del recién nacido se evalúa con pruebas de anticuerpos maternos y no con Coombs directo en la sangre del neonato, la opción C es errónea ya que las hemolíticos no inmunes no presentan anticuerpos en la superficie eritrocitaria, y la opción D es irrelevante porque la prueba no se aplica a anemias no hemolíticas.'),
  (270, 'El grupo sanguíneo AB del sistema ABO es receptor universal porque sus glóbulos rojos carecen de anticuerpos anti‑A y anti‑B en el plasma, lo que permite recibir transfusiones de cualquier donante sin riesgo de reacción hemolítica; además, la presencia de antígenos A y B en la superficie eritrocítica no provoca inmunogenicidad cuando se transfieren a un receptor AB. Las demás opciones son incorrectas: el grupo A (B) presenta anticuerpos anti‑B (anti‑A) que impedirían la aceptación de sangre de los grupos correspondientes, y el grupo 0, aunque es donante universal, posee anticuerpos anti‑A y anti‑B que lo hacen incompatible con los receptores de A, B o AB.'),
  (271, 'En la leucemia mieloide aguda tipo M3 (leucemia promielocítica aguda) la presentación típica incluye una disminución de los leucocitos totales, es decir, leucopenia, porque la proliferación de células inmaduras ocupa la médula sin generar suficientes leucocitos funcionales; además, la presencia de trombocitopenia y anemia es frecuente, pero la leucopenia es la alteración más característica que se observa en los hemogramas de estos pacientes, mientras que la neutrofilia, trombocitosis y poliglobulia son hallazgos que se asocian con otras entidades mieloproliferativas o linfoproliferativas, por lo que las opciones B, C y D son inadecuadas.'),
  (272, 'El mieloma múltiple se caracteriza por la producción excesiva de inmunoglobulinas monoclonales, lo que provoca anemia por aplasia medular, proteinuria de Bence‑Jones (fragmentos ligeros de Ig en la orina) y una hiperproteinemia que se refleja en la densidad de la proteína en el suero; la hipocalcemia, en cambio, es típica de la enfermedad de Paget, hipopotasemia o hiperglucemia, y no se asocia con la sobreproducción de inmunoglobulinas, por lo que no constituye un hallazgo de laboratorio de esta patología. Las demás opciones describen manifestaciones clínicas y de laboratorio que sí se observan en el mieloma múltiple.'),
  (273, 'El D‑dímero es el fragmento de fibrina que se libera cuando la trombina activa la fibrinógeno y la fibrina se degrada por la plasmina; su presencia indica actividad de coagulación y fibrinólisis reciente. Cuando el valor de D‑dímero se mantiene dentro de la referencia normal, se infiere que no ha habido formación ni lisis de coágulos significativos, por lo que la sospecha de trombosis activa queda descartada; este parámetro es altamente sensible pero poco específico, y su ausencia de elevación es suficiente para excluir diagnósticos trombóticos en la mayoría de los contextos clínicos. En contraste, la proteína C, la antitrombina III y la proteína S son anticoagulantes naturales cuya deficiencia aumenta el riesgo de trombosis, pero la normalidad de sus niveles no descarta la presencia de un coágulo, ya que la trombosis puede ocurrir con niveles normales de estos factores; además, su medición no refleja la actividad fibrinolítica actual. Por lo tanto, las opciones A, C y D son incorrectas porque la normalidad de estos parámetros no elimina la posibilidad de trombosis.'),
  (274, 'Los pacientes con enfermedad de Addison presentan insuficiencia suprarrenal primaria, lo que implica una deficiencia absoluta de cortisol y, en la mayoría de los casos, de aldosterona, debido a la destrucción autoinmune o a otras causas que impiden la síntesis adecuada de estas hormonas; por ello la opción B es la única que describe la causa fisiopatológica de la enfermedad. La alternativa A es incorrecta porque la enfermedad de Addison no provoca sobreestimulación hormonal sistémica, sino la ausencia de glucocorticoides y mineralocorticoides, y la muerte prematura se relaciona con crisis adrenocorticales, no con exceso hormonal. La opción C es errónea porque la prolactina no está alterada en la insuficiencia suprarrenal primaria; la alteración hormonal se limita a cortisol y aldosterona. La alternativa D resulta inexacta, ya que aunque la deficiencia de cortisol puede afectar el metabolismo óseo, el diagnóstico inicial se basa en síntomas de hipoadrenalismo (fatiga, hipotensión, hipoglucemia) y no en un trastorno óseo.'),
  (275, 'La miastenia grave se caracteriza por una disfunción autonómica en la unión neuromuscular, donde los anticuerpos dirigidos contra los receptores de acetilcolina reducen su número y funcionalidad, provocando una disminución de la transmisión sinapsis y, por ende, una debilidad muscular progresiva; por tanto la opción D describe el mecanismo patológico subyacente. Las demás alternativas son inexactas: la opción A se refiere a una alteración de la síntesis de acetilcolina, que no es el hallazgo típico de la miastenia; la B menciona la miosina, una proteína contráctil del sarcómero cuya cantidad no se ve afectada en esta enfermedad; y la C habla de troponina C, cuya función está relacionada con la regulación de la contracción muscular, pero no presenta déficit en la miastenia grave.'),
  (276, 'Los cuerpos de Lewy son inclusiones citoplasmáticas intrínsecamente compuestas por agregados de α‑sinucleína, una proteína de 140 aminoácidos que se localiza en la periferia de las terminales sinápticas y que, en su forma fibrilar, constituye la base de la patología de la enfermedad de Parkinson y de otras demencias Lewy; la acumulación de esta proteína altera la función sináptica, la dinámica del citoesqueleto y la señalización de la vía de autophagía, lo que explica la neurodegeneración observada. La opción A, la proteína tau, es el componente principal de los ovillos neurofibrilares de la enfermedad de Alzheimer y no está implicada en los cuerpos de Lewy. La C, la β‑sinucleína, no existe; la β‑amiloide (opción D) forma placas extraneurales en Alzheimer, pero no constituye los cuerpos de Lewy. Por tanto, la única alternativa que describe el componente molecular real de los depósitos es la α‑sinucleína.'),
  (277, 'En la enfermedad de Parkinson la pérdida progresiva de neuronas dopaminérgicas en la sustancia negra pars compacta conduce a una reducción marcada de la dopamina en el circuito cortico‑estriado‑cerebelar, lo que explica los síntomas motores característicos; por tanto, la alteración más frecuente es la de la dopamina, opción B. La noradrenalina, aunque también disminuye en etapas avanzadas, no es la principal vía afectada y su déficit no explica los signos motores primarios; la serotonina se ve alterada principalmente en la fase de síntomas no motores y su déficit no es tan frecuente; la acetilcolina, al contrario, suele aumentar en respuesta al déficit dopaminérgico, por lo que su alteración no es la más frecuente.'),
  (278, 'El mecanismo de compensación ante un bombeo cardíaco insuficiente se basa en la activación del sistema simpático, que aumenta la frecuencia y la contractilidad del miocardio; la estimulación del eje renina‑angiotensina‑aldosterona, que eleva la presión arterial y el retorno venoso, y el efecto de Frank‑Starling, que incrementa el gasto cardíaco al aumentar la pre‑carga; por tanto, la opción D, que menciona una disminución de la angiogénesis, no forma parte de la respuesta inmediata y fisiológica al bajo gasto, ya que la angiogénesis es un proceso de remodelación a largo plazo y no un mecanismo compensatorio agudo. Las opciones A, B y C describen respuestas fisiológicas bien documentadas, mientras que la D se agrupa con las demás como incorrecta por no corresponder a un mecanismo compensador del sistema cardiovascular.'),
  (279, 'El cambio genético característico de la leucemia promielocítica aguda es la translocación t(15;17)(q22;q12) que genera el gen de fusión PML‑RARA; por tanto la opción D es la única que menciona el receptor de ácido retinoico α, cuyo dominio de unión a retinoides se conserva en la fusión y es el objetivo de la terapia con ácido retinoico isómero A (ATRA). Las demás alternativas son erróneas: la opción A sugiere una mutación puntual, cuando se trata de una translocación cromosómica; la B describe una tirosina cinasa hiperactiva, típica de leucemias con fusión BCR‑ABL o FLT3‑ITD, pero el complejo PML‑RARA no es una tirosina cinasa; y la C menciona la fusión TMPRSS2‑ETS, que se observa en tumores de próstata, no en la leucemia promielocítica aguda.'),
  (280, 'La opción C es la que describe con precisión el mecanismo patológico de la deficiencia de G6PD: las variantes hemolíticas alteran la conformación de la enzima, lo que la hace más vulnerable a la oxidación y a la degradación proteolítica, reduciendo la producción de NADPH y, por ende, el glutathion reducido necesario para neutralizar los radicales libres; las demás alternativas son incorrectas porque la G6PD cataliza la oxidación de NADP+ a NADPH, no la reducción de NAD a NADH (A), la herencia de la deficiencia es ligada al cromosoma X y, por tanto, no es autosómica recesiva (B), y la actividad de la enzima no “impide” la oxidación del glutathion sino que la produce al generar NADPH, que alimenta la regeneración del GSH (D).'),
  (281, 'La mutación del gen VHL produce una proteína VHL defectuosa que ya no forma el complejo de ubiquitina ligasa que reconoce y marca al factor inducible por hipoxia‑α (HIF‑1α) para su degradación proteasómica; por tanto, la opción B es la que describe correctamente el mecanismo, y la opción A también es coherente porque la falta de degradación implica que el HIF‑1α permanece estable en condiciones normóxicas. La pérdida de la función de VHL conduce a un aumento de la síntesis de factores de crecimiento angiogénicos, como el factor de crecimiento endotelial vascular (VEGF), lo que explica la opción D. En cuanto a la opción C, las mutaciones de VHL son pérdidas de función, no ganancia de función, ya que la proteína VHL pierde su capacidad de degradar HIF‑1α; por lo tanto, la afirmación de que son mutaciones de ganancia de función es incorrecta. Las demás opciones son incorrectas porque describen de forma coherente el efecto fisiológico de la pérdida de función de VHL, mientras que la opción C presenta un concepto opuesto.'),
  (282, 'La reacción de Fenton, que produce radicales hidroxilo a partir de peróxido de hidrógeno, requiere el ion ferroso (Fe²⁺) como catalizador; el hierro se oxida a Fe³⁺ y luego se reduce de nuevo a Fe²⁺, generando así los radicales libres que dañan biomoléculas, razón por la cual el hierro es el elemento químico relacionado con esta generación; el selenio, aunque es un micronutriente con actividad antioxidante, no participa en la reacción de Fenton, el zinc es un cofactor de enzimas antioxidantes pero tampoco cataliza la formación de radicales, y el cloro, aunque puede formar especies reactivas en procesos de oxidación, no actúa como catalizador en la reacción de Fenton; por tanto, las opciones B, C y D son incorrectas porque no cumplen el papel catalítico específico del hierro en la generación de radicales libres.'),
  (283, 'La caquexia crónica se asocia con la sobreproducción de la citoquina proinflamatoria factor de necrosis tumoral alfa (TNF‑α), la cual induce catabolismo proteico, pérdida de masa muscular y adiposa, alteraciones metabólicas y anorexia; su papel en la respuesta inflamatoria sistémica y la activación de vías de degradación de proteínas (p. ej., vía ubiquitina‑proteasoma) explica su implicación clínica en infecciones crónicas y neoplasias. El interferón‑γ, aunque también es proinflamatorio, no es el mediador principal de la caquexia y su perfil de acción se centra en la activación de macrófagos y respuesta antiviral; el factor de crecimiento transformante β participa en la remodelación tisular y fibrosis, no en la pérdida de peso sistémica; la interleucina‑10 es antiinflamatoria y favorece la supresión de la respuesta inflamatoria, por lo que no contribuye a la caquexia.'),
  (284, 'La deficiencia de 21β‑hidroxilasa impide la conversión de 17‑hidroxiprogesterona y 17‑hidroxiesteroides a 11‑deoxicortisol y aldosterona, por lo que se produce una acumulación de precursores y una disminución de los glucocorticoides y mineralocorticoides, lo que provoca hipocortisolismo (C) y una reducción de la producción de mineralocorticoides (D); la falta de cortisol desencadena un aumento de la liberación de ACTH, lo que estimula la hiperplasia suprarrenal (A). La afirmación B es incorrecta porque, aunque la deficiencia de 21β‑hidroxilasa reduce la síntesis de cortisol y aldosterona, la excreción de 17‑cetosteroides no disminuye; al contrario, los precursores 17‑hidroxiprogesterona y 17‑hidroxiesteroides se acumulan y se excretan en mayor cantidad, por lo que las concentraciones urinarias de 17‑cetosteroides aumentan, no se reducen; las demás opciones son correctas.'),
  (285, 'La mutación del factor V de Leiden provoca una sustitución de arginina por glutamina en la posición 506, lo que impide la clivación del factor V por la proteína C activada en presencia de proteína S; por tanto el factor V permanece activo y favorece la generación de trombina, elevando el riesgo de trombosis venosa profunda y trombosis tromboembólica; la resistencia a la inactivación es la característica que distingue a esta variante, mientras que la herencia es autosómica dominante y no ligada al sexo, el calcio no se ve afectado en la cascada de coagulación y el riesgo trombótico se asocia principalmente a trombosis venosa, no arterial, por lo que las opciones B, C y D resultan incorrectas.'),
  (286, 'El fármaco que inhibe la fosfodiesterasa 4 (PDE4) y se emplea en la psoriasis es el apremilast, pues su mecanismo de acción consiste en elevar los niveles de cAMP en células inmunitarias, reduciendo la producción de citocinas proinflamatorias como IL‑23, IL‑17 y TNF‑α, lo que atenúa la inflamación cutánea característica de la enfermedad; las demás opciones son inactivos en este contexto: el roflumilast es un inhibidor de PDE4 usado en la EPOC, el tildrakizumab es un anticuerpo monoclonal que bloquea IL‑23 y el montelukast es un antagonista de los receptores de leukotrienos, por lo que no cumplen la función de inhibidor de PDE4 en la psoriasis.'),
  (287, 'La determinación de la actividad de la tiopurina metiltransferasa (TPMT) se indica en el contexto del uso de azatioprina, ya que esta enzima cataliza la metilación de la azatioprina y sus metabolitos, convirtiéndolos en compuestos inactivos; la variabilidad genética de TPMT puede provocar una acumulación de metabolitos tóxicos (como 6‑fluorouridina) y, por tanto, una mayor incidencia de toxicidad hematológica, por lo que el perfil de TPMT permite ajustar la dosis o considerar alternativas terapéuticas; las demás opciones (mesalazina, vedolizumab y olsalazina) son fármacos de acción antiinflamatoria o inmunomoduladora que no dependen de la vía de metabolización por TPMT, de modo que la prueba no tiene relevancia clínica para ellos.'),
  (288, 'El riluzol es el único fármaco aprobado para la esclerosis lateral amiotrófica y su mecanismo de acción consiste en inhibir la liberación de glutamato, reduciendo la excitotoxicidad que contribuye a la muerte de las neuronas motoras; por tanto la afirmación B es la que se corresponde con la evidencia clínica y farmacológica, mientras que la opción A menciona al natalizumab, un modulador de la adhesión celular usado en esclerosis múltiple, sin eficacia demostrada en la SLA; la alternativa C es falsa porque el riluzol sí está comercializado y aprobado; y la opción D alude al acetato de glatirámero, otro fármaco de la esclerosis múltiple que no tiene indicación ni biodisponibilidad oral relevante en la SLA, por lo que las tres respuestas restantes son incorrectas.'),
  (289, 'La opción B es la que presenta la afirmación errónea: la hipotensión no constituye el efecto adverso más frecuente asociado al uso de eritropoyetina; los eventos más comunes son la hipertensión arterial, la trombosis y la anemia refractaria, mientras que la hipotensión se observa con menor frecuencia. En contraste, la opción A es válida porque la eficacia de la eritropoyetina depende intrínsecamente de la disponibilidad de hierro, ya que el hierro es el cofactor esencial para la síntesis de hemoglobina y la eritropoyesis; sin hierro suficiente, la respuesta eritropoyética se ve limitada. La opción C es correcta porque existen formulaciones de eritropoyetina (por ejemplo, epoetina alfa y darbepoetina alfa) que se pueden administrar tanto por vía subcutánea como intravenosa, permitiendo flexibilidad en la práctica clínica. La opción D también es cierta, pues la administración subcutánea produce una absorción más lenta y sostenida, lo que reduce la frecuencia de dosis y la cantidad total requerida, optimizando la respuesta y minimizando los costos; sin embargo, la afirmación de que la absorción más lenta “reduce la dosis necesaria” se interpreta como una ventaja clínica, no como un error. Por tanto, las demás opciones son correctas, mientras que la B se agrupa con la incorrecta por describir un efecto adverso poco frecuente.'),
  (290, 'La asociación fingolimod‑receptor de esfingosina‑1‑fosfato (S1P) es coherente con su mecanismo de acción, pues el fármaco actúa como agonista parcial que provoca la internalización del receptor y la retención de linfocitos en la médula ósea; alemtuzumab es un anticuerpo monoclonal que reconoce el antígeno CD52 presente en linfocitos y macrófagos, y ocrelizumab dirige al CD20, un marcador de linfocitos B, reduciendo su número; en cambio, natalizumab es un anticuerpo monoclonal que se une a la integrina α4β1 (VLA‑4) en la superficie de leucocitos, bloqueando su adhesión a la molécula de adhesión vascular endotelial (VCAM‑1) y evitando su migración al SNC, por lo que la diana indicada como receptor de IL‑2 es incorrecta. Las opciones A, B y C describen diana‑fármaco válidas, mientras que la opción D presenta un error porque el receptor de IL‑2 no es el objetivo de natalizumab.'),
  (291, 'El trastorno del control de impulsos, incluido el juego patológico, se asocia principalmente con la estimulación de los receptores dopaminérgicos, ya que la dopamina es el neurotransmisor central del sistema de recompensa y motivación; los agonistas dopaminérgicos aumentan la liberación y la actividad dopaminérgica en el núcleo accumbens, lo que favorece la sensación de placer y la repetición de conductas adictivas, por lo que la opción A describe el mecanismo farmacológico que explica este efecto; las opciones B, C y D son incorrectas porque los inhibidores de la acetilcolinesterasa aumentan la acetilcolina y no están vinculados a impulsos de juego, los antagonistas NMDA modulan la excitabilidad glutamatérgica sin producir ese tipo de adicción, y los inhibidores de MAO‑A elevan la norepinefrina y serotonina, pero su perfil de efectos secundarios no incluye trastornos de control de impulsos como el juego; por tanto, solo la opción A se ajusta al mecanismo patológico descrito.'),
  (292, 'El fármaco que presenta una relación fármaco‑diana molecular incorrecta es el abatacept; este agente es una proteína de fusión que combina la región de unión a CD80/CD86 del co‑estimulador de la respuesta T, no un antagonista del TNF‑α, por lo que su mecanismo de acción no implica la neutralización del citocina. En cambio, el rituximab es un anticuerpo monoclonal dirigido contra CD20 en linfocitos B, el tocilizumab es un anticuerpo monoclonal que bloquea el receptor de IL‑6, y el tofacitinib es un inhibidor selectivo de las Janus Kinasa (JAK), modulando la señalización de múltiples citocinas. Las opciones restantes (A, C y D) describen correctamente la diana molecular de cada fármaco, mientras que la opción B agrupa erróneamente a abatacept con la clase de inhibidores del TNF‑α.'),
  (293, 'La risperidona es el antipsicótico de la lista que posee indicación específica para el tratamiento de la agitación y agresividad asociadas a la enfermedad de Alzheimer, ya que su perfil farmacológico como antagonista de los receptores D2 y 5‑HT2A, combinado con la evidencia de eficacia en estudios clínicos de pacientes con demencia, lo convierte en la opción aprobada por las guías de práctica clínica; en cambio, la sulpirida, aunque es un antipsicótico típico, no tiene indicación en demencia y su perfil de efectos secundarios (hipotensión ortostática, disfunción sexual) lo hace menos adecuado; la clozapina, antipsicótico atípico con indicaciones en esquizofrenia resistente, presenta un riesgo de agranulocitosis y no está recomendada para la demencia; el zuclopentixol, otro típico, tampoco cuenta con evidencia ni aprobación para el manejo de la conducta agresiva en Alzheimer, y su uso se reserva a trastornos psicóticos más agudos.'),
  (294, 'El omeprazol, inhibidor de la bomba H⁺/K⁺-ATPasa, se administra preferentemente en ayunas porque su absorción es mayor cuando el estómago está vacío, lo que maximiza la disponibilidad de la molécula para su unión a la enzima; por ello la opción A es coherente con la práctica clínica. La hipermagnesemia se asocia con inhibidores de la bomba de la H⁺/K⁺-ATPasa en el intestino delgado, pero el omeprazol no produce alteraciones significativas en los niveles séricos de magnesio, incluso en tratamientos prolongados, por lo que la afirmación B es falsa. El bloqueo prolongado de la secreción ácida reduce la descomposición gástrica de la vitamina B12, disminuyendo su absorción en el íleon, lo que justifica la opción C. Finalmente, la inhibición máxima de la secreción ácida suele alcanzarse después de 3 a 4 días de terapia continua, lo que confirma la opción D. Por tanto, la única declaración que carece de fundamento es la B, mientras que las demás se sustentan en datos farmacológicos y clínicos bien establecidos.'),
  (295, 'La opción C es incorrecta porque las estatinas están clasificadas como categoría X por la FDA y son absolutamente contraindicadas en el embarazo, ya que inhiben la síntesis de colesterol en el feto y pueden causar defectos congénitos; el fármaco de elección en embarazadas es la niacina o el ácido nicotínico en dosis bajas, pero no las estatinas. En cambio, la opción A es verdadera: los fibratos, al inhibir la lipasa lipoproteínica, pueden aumentar la concentración de anticoagulantes orales como la warfarina, incrementando el riesgo de sangrado. La opción B también es cierta: la combinación de fibratos con estatinas eleva el riesgo de rabdomiólisis, especialmente en dosis altas o en pacientes con factores de riesgo. Finalmente, la opción D es correcta porque el fluconazol inhibe la CYP3A4, enzima que metaboliza la atorvastatina, lo que lleva a concentraciones plasmáticas elevadas y mayor riesgo de toxicidad muscular.'),
  (296, 'El tratamiento de primera línea para la hiperplasia benigna de próstata (HBP) se basa en la reducción de la resistencia de la vejiga a la salida urinaria, y los antagonistas α‑1 adrenérgicos logran esta acción bloqueando los receptores α‑1 en la musculatura lisa de la próstata y el cuello vesical, lo que provoca relajación del músculo liso, disminución de la presión de salida y mejora de los síntomas urinarios; por ello la opción A es la adecuada. Los inhibidores de la fosfodiesterasa 5 (opción B) se utilizan en disfunción eréctil y, aunque pueden aliviar síntomas de HBP, no son la primera elección; los inhibidores de la 17‑α‑hidroxilasa (opción C) reducen la síntesis de andrógenos y se emplean en cáncer de próstata, no en HBP; los análogos de prostaglandinas E1 (opción D) se usan en insuficiencia cardíaca y no tienen efecto sobre la próstata.'),
  (297, 'El topiramato es el antiepiléptico de primera línea indicado para el síndrome de Lennox‑Gastaut, ya que su mecanismo de acción (bloqueo de canales de Na⁺ y K⁺, aumento de GABA y antagonismo de AMPA) reduce la frecuencia y la gravedad de las crisis atónicas y mioclónicas que caracterizan a esta entidad, y la evidencia clínica respalda su eficacia; en cambio, el ácido valproico es un inhibidor de la CYP450, no un inductor, por lo que la opción A es falsa; el levetiracetam tiene un perfil de teratogenicidad bajo y no se considera uno de los antiepilépticos más teratógenos, por lo que la opción C es incorrecta; y el litio, aunque es antipsicótico y estabilizador del ánimo, no se emplea para las crisis de ausencia, que se tratan con carbamazepina, valproato o ethosuximida, lo que invalida la opción D.'),
  (298, 'La asociación que resulta incorrecta es la de captopril con hipopotasemia, porque los inhibidores de la enzima convertidora de angiotensina (IECA) como el captopril aumentan la concentración de angiotensina II y de bradicinina, lo que favorece la secreción de aldosterona y, en consecuencia, la excreción de potasio; por tanto, la hipopotasemia es un efecto esperado, no una ausencia. En contraste, la furosemida, un diurético de asa, provoca pérdida de sodio y agua y, al disminuir el volumen intravascular, estimula la aldosterona, reduciendo el potasio y provocando hipocalcemia; el aliskirén, inhibidor de la COX-1, puede disminuir la excreción renal de potasio y favorecer la hiperpotasemia; y la hidroclorotiazida, diurético tiazídico, reduce la excreción de calcio, provocando hipercalcemia. Las opciones A, B y D describen efectos fisiológicos coherentes con la farmacología de cada fármaco, mientras que la opción C presenta un contraste lógico con la acción esperada del IECA.'),
  (299, 'La opción C es incorrecta porque la mutación de KRAS activa la vía de señalización downstream de EGFR de forma constitutiva, de modo que la inhibición de la receptora con cetuximab, un anticuerpo monoclonal anti‑EGFR, no afecta a la señalización intracelular y el fármaco pierde eficacia; en cambio, las otras combinaciones son terapéuticamente válidas: la mutación V600E de BRAFV conduce a una BRAF hiperactiva que es bloqueada por dabrafenib, el fusión EML4‑ALK produce un quimérico tirosina quinasa que es inhibido por crizotinib, y la mutación L858R de EGFR mantiene la dependencia de la señal de EGFR que es suprimida por gefitinib. Las opciones A, B y D son coherentes con la lógica de terapia dirigida.'),
  (300, 'La opción A es incorrecta porque la neuropatía periférica no es el efecto adverso más frecuente de irinotecán; este fármaco provoca principalmente toxicidad gastrointestinal (diarrea, náuseas) y hematológica (neutropenia), siendo la neuropatía un efecto secundario menos frecuente y asociado más con el agente taxol. La opción B es válida, pues el cisplatino es bien conocido por su ototoxicidad, manifestándose como pérdida auditiva irreversible. La opción C también es correcta, ya que el paclitaxel se emplea con eficacia en tumores de ovario y de pulmón, siendo uno de los agentes de primera línea en ambos tipos de cáncer. La opción D es adecuada, pues el leucovorin (folato) se administra para rescatar la célula normal y disminuir la toxicidad de metotrexato, especialmente la nefrotoxicidad y la mucositis. Por lo tanto, las respuestas B, C y D son correctas, mientras que solo la A presenta un error.'),
  (301, 'El cabergolina, aunque es un agonista dopaminérgico de alta afinidad y potencia, se reserva principalmente para el tratamiento de la hipopituitarismo y la enfermedad de Parkinson, y su uso en el síndrome de piernas inquietas está desaconsejado por el riesgo de efectos secundarios sistémicos y la falta de evidencia de beneficio clínico en esta patología; en contraste, ropinirol, pramipexol y rotigotina son agonistas de la D2/D3 que actúan sobre los receptores en el tronco encefálico y la médula espinal, reduciendo la sensación de tirones y la necesidad de movimiento, y están aprobados y respaldados por estudios clínicos específicos para el síndrome de piernas inquietas. Las opciones A, B y C comparten la característica de ser agonistas de la D2/D3 con perfil farmacocinético y farmacodinamia adecuados para RLS, mientras que la opción D difiere en su indicación clínica y en la falta de respaldo empírico para esta enfermedad.'),
  (302, 'La opción A resulta incorrecta porque, en la insuficiencia cardíaca, los fármacos que aumentan la precarga (por ejemplo, los diuréticos o los antagonistas de la aldosterona) reducen la carga de volumen sobre el ventrículo y, por tanto, disminuyen la precarga; no se busca aumentarla, ya que un incremento de la precarga empeora la función sistólica y eleva la presión venosa central, provocando congestión. En contraste, la hipertensión arterial (B) es una causa frecuente de insuficiencia cardíaca, pues la presión arterial elevada obliga al ventrículo a generar más fuerza de contracción, lo que con el tiempo conduce a remodelación y disfunción. La cardiopatía isquémica (C) puede desencadenar arritmias al producir isquemia de la masa miocárdica, alterando el potencial de acción y la conducción eléctrica. Finalmente, la modulación del sistema nervioso simpático y del sistema renina‑angiotensina‑aldosterona (D) es una estrategia terapéutica habitual, con betabloqueantes, inhibidores de la ECA o antagonistas de los receptores de angiotensina y antagonistas de la aldosterona, que reducen la carga de trabajo cardíaco y la retención de líquidos. Las demás opciones comparten la base de evidencia fisiopatológica y farmacológica, mientras que la opción A se basa en una premisa fisiológica errónea.'),
  (303, 'La opción B es la que se emplea habitualmente en el tratamiento de la enfermedad de Parkinson porque la dopa descarboxilasa (DDC) cataliza la descarboxilación de L‑DOPA a dopamina en los tejidos periféricos, reduciendo la cantidad que llega al SNC; el inhibidor de DDC (carbidopa o benserazida) bloquea esta vía sin afectar la actividad central, evitando la formación de dopamina fuera del cerebro y sus efectos adversos. La inhibición de MAO‑A (A) o MAO‑B (D) no previene la conversión periférica de L‑DOPA a dopamina y, además, MAO‑B se dirige principalmente a la degradación de dopamina en el SNC, mientras que MAO‑A metaboliza principalmente serotonina y norepinefrina; por tanto, su uso no es pertinente para este fin. El inhibidor de COMT (C) reduce la catálisis de la dopamina a 3‑metoxidopa, pero no impide la descarboxilación de L‑DOPA, por lo que no es la medida primaria para evitar la conversión periférica.'),
  (304, 'La lamotrigina es la opción preferida en un paciente con trastorno bipolar porque su mecanismo de acción estabiliza la actividad neuronal mediante la inhibición de la liberación de glutamato y la reducción de la excitabilidad de los canales de sodio, lo que previene tanto episodios maníacos como depresivos sin provocar sedación ni alteraciones del estado de ánimo que suelen asociarse a los antiepilépticos tradicionales; además, su perfil de efectos secundarios es más favorable en este contexto. La fenitoína, aunque estabiliza el estado de ánimo, puede desencadenar efectos adversos cutáneos graves y alteraciones de la función hepática, por lo que su uso se reserva a casos específicos. El topiramato, aunque posee actividad antiepiléptica, puede inducir depresión y disfunción cognitiva, lo que lo hace menos idóneo para el trastorno bipolar. La pregabalina, aunque estabiliza la excitabilidad neuronal, se utiliza principalmente en neuropatía y fibromialgia, y su eficacia en el trastorno bipolar es limitada.'),
  (305, 'Los nitratos actúan como donantes de óxido nítrico (NO) que, al activarse la guanililciclasa en la capa muscular lisa vascular, elevan los niveles de GMPc y provocan relajación de los vasos; por lo tanto, su eficacia depende de la integridad de la señal de NO y de la respuesta de la musculatura lisa, no del endotelio intacto, que solo participa en la generación de NO por otras vías, lo que hace que la afirmación A sea falsa; las opciones B, C y D son verdaderas porque los nitratos reducen la precarga al dilatar venas, se emplean en la angina de pecho para disminuir la demanda de oxígeno y se enlazan a receptores que activan la guanililciclasa, respectivamente.'),
  (306, 'La unión de fármacos a proteínas plasmáticas, principalmente a la albúmina, es un proceso saturable porque las proteínas disponen de un número finito de sitios de unión; cuando la concentración de fármaco excede la capacidad de estos sitios, la fracción libre aumenta de forma no lineal, alterando la farmacocinética y la eficacia; las demás alternativas son erróneas: la alta unión a proteínas reduce el volumen aparente de distribución (opción A), la interacción con la albúmina es específica y depende de la estructura del fármaco (opción B), y la unión a proteínas sí afecta la velocidad de distribución al limitar la cantidad de fármaco disponible para difundir en los tejidos (opción D).'),
  (307, 'La fosfolipasa C (PLC) se activa mediante la interacción con el subgrupo Gq de las proteínas G heterotriméricas; la unión de Gαq al receptor acoplado a G (GPCR) libera la subunidad Gαq que a su vez activa la PLCβ, catalizando la hidrólisis del PIP₂ en IP₃ y DAG, mediadores de la señal intracelular; las proteínas Gs, Gi y Go no participan en la activación de la PLC, pues Gs estimula la adenilato ciclasa, Gi inhibe la misma y Go está involucrado en la regulación de canales iónicos y la señalización de la vía de la proteína C, por lo que las opciones A, B y C son incorrectas.'),
  (308, 'Los anticolinérgicos, al antagonizar los receptores muscarínicos de la acetilcolina, inhiben la actividad parasimpática en órganos efectores; por ello reducen el peristaltismo intestinal (A), disminuyen la secreción salival (C) y dilatan la pupila (D) mediante bloqueo de los receptores M3 en el músculo ciliar, lo que provoca midriasis. En cambio, la vasoconstricción (B) no es un efecto típico de estos fármacos; los receptores muscarínicos en el sistema vascular son mayoritariamente M2 y su activación provoca vasodilatación, por lo que el bloqueo no produce vasoconstricción. Las opciones A, C y D son efectos fisiológicos esperados, mientras que la opción B se agrupa con la única alternativa que describe un resultado fisiológico opuesto al de los anticolinérgicos.'),
  (309, 'La entacapona actúa como inhibidor de la dopa descarboxilasa periférica, impidiendo la conversión de levodopa en dopamina fuera del SNC y, por tanto, elevando la concentración plasmática de levodopa disponible para cruzar la barrera hematoencefálica; esta es la razón por la que se emplea como coadyuvante. Las demás opciones son incorrectas: la entacapona no es un agonista dopaminérgico, por lo que la alternativa B no describe su mecanismo; no inhibe la dopa descarboxilasa central, sino la periférica, por lo que la opción C es imprecisa; y no es un inhibidor de la monoaminooxidasa B, lo que descarta la alternativa D.'),
  (310, 'Los triptanes son agonistas selectivos de los receptores 5‑HT1B/1D que, al activarse, provocan la vasoconstricción de las arterias cerebrales y la inhibición de la liberación de neuropeptidos proinflamatorios, lo que reduce la migraña; por ello su uso se reserva a episodios agudos y no a la profilaxis, y su administración se puede dar por vía oral, intranasal o subcutánea, con biodisponibilidad aceptable en la forma oral; además, aunque se debe tener precaución en pacientes con enfermedad cardiovascular, no son absolutamente contraindicados, sino que se aconseja su uso con cautela, por lo que la afirmación de que están contraindicados en todos los pacientes con enfermedad cardiovascular es incorrecta. Las demás opciones son erróneas: la A describe correctamente el mecanismo de acción, la B confunde el uso agudo con la profilaxis, y la C sobreestima la biodisponibilidad oral, pues los triptanes orales son efectivos y se utilizan ampliamente.'),
  (311, 'Las fenotiazinas antieméticas actúan como antagonistas de los receptores dopaminérgicos D2 ubicados en la zona quimiorreceptora del gatillo, bloqueando la transmisión dopaminérgica que desencadena el reflejo nauseoso; su acción central en el centro de emesis del bulbo raquídeo y la zona quimiorreceptora es la responsable de su eficacia frente a las náuseas y vómitos de origen metabólico o farmacológico, mientras que su efecto gastrointestinal se limita al bloqueo periférico de D2 en el tracto digestivo. La opción A es incorrecta porque las fenotiazinas no actúan sobre los receptores serotoninérgicos del tracto gastrointestinal, sino sobre los D2; la B es errónea pues son antagonistas, no agonistas, de los D2; la D es falsa porque no son agonistas parciales de los receptores de serotonina, sino antagonistas de dopamina.'),
  (312, 'La podofilotoxina, al ser un alcaloide fenólico de origen vegetal, actúa inhibiendo la microtubulosa y la síntesis de ADN, lo que provoca la muerte de células proliferantes; por ello se emplea clínicamente como agente antineoplásico y, más específicamente, en la terapia tópica de lesiones condilomatosas, como los condilomas acuminados, donde su acción citotóxica elimina las células anómalas del epitelio genital; las demás opciones no corresponden a su mecanismo de acción ni a sus indicaciones aprobadas: la podofilotoxina no tiene efecto sobre la motilidad gastrointestinal ni sobre la función hepática, y su uso no se asocia con la reducción de neuralgias post‑herpéticas, por lo que las alternativas B, C y D resultan incorrectas.'),
  (313, 'La raíz de Eleutherococcus senticosus (conocida como ginseng siberiano) contiene principalmente glicosilados de triterpenoides pentacíclicos, denominados eleutherosidos, que son saponósidos triterpénicos pentacíclicos; por lo tanto la opción B describe correctamente la naturaleza química de sus principios activos, ya que los eleutherosidos presentan una estructura pentacíclica típica de los triterpenos y no de los esteroides. La opción A es errónea porque Ruscus aculeatus (ruisa) contiene saponósidos triterpénicos tetracíclicos, no pentacíclicos, y la afirmación confunde la cantidad de anillos. La opción C es falsa porque la corteza de Aesculus hippocastanum (cascara de fresno) contiene principalmente aescina, que es un saponósido triterpénico pentacíclico, pero la frase “contiene en su corteza mayoritariamente β‑aescina” es incorrecta, pues la aescina es el principal compuesto, no la β‑aescina. La opción D resulta inexacta porque los principios activos de la raíz de Panax ginseng son ginsengósidos, que son saponinas triterpénicas, no esteroídicas; la confusión surge al asociar erróneamente la estructura esteroidal con los ginsengósidos.'),
  (314, 'El harpagofito (Harpagophytum procumbens) se utiliza tradicionalmente por sus efectos antiinflamatorios, los cuales se atribuyen principalmente a la actividad de los compuestos fenólicos y a la inhibición de la síntesis de prostaglandinas; por ello la opción C es la que describe la característica farmacológica más destacada de la planta, mientras que la alternativa A es incorrecta porque los estudios clínicos no han demostrado que los principios activos aislados produzcan una mayor eficacia que la preparación completa, la opción B es errónea al identificar la corteza como la parte activa cuando la raíz y su corteza interna son las que se emplean, y la opción D resulta falsa porque el harpagósido pertenece a la familia de los iridoides, no a los secoiridoides.'),
  (315, 'La ergometrina es la amida del ácido lisérgico y 2‑aminopropanol, pues su estructura química corresponde a la reacción de esterificación del ácido lisérgico con 2‑aminopropanol, dando el compuesto que se utiliza en obstetricia para inducir contracciones uterinas; las demás opciones son incorrectas: la nicergolina no es un alcaloide del cornezuelo, sino un derivado de la nicotinamida con efectos vasodilatadores y no midriáticos; la ergotoxina no es un grupo de alcaloides, sino un subgrupo de ergotamina que no se emplea de forma rutinaria en terapia; la ergocristina es una amida peptídica, pero su uso principal es en la prevención de la migraña crónica, no en crisis agudas.'),
  (316, 'La afirmación incorrecta es la B: la capsaicina no es un tetraterpeno ni se utiliza como colorante, sino que es un alcaloide capsaicinoide de la familia de los capsaicinoides que se emplea principalmente como irritante y analgésico tópico; su estructura contiene un anillo de piperidina unido a un radical de capsaicinoide, no un tetraterpeno. En cambio, la artemisinina (A) es una lactona sesquiterpénica derivada de Artemisia annua y se emplea por su potente actividad antipalúdica; la camptotecina (C) es un alcaloide quinolínico que se utiliza como agente antitumoral; y el taxol (D) es un diterpeno que también se emplea en la quimioterapia de tumores sólidos. Las demás opciones son correctas porque describen adecuadamente la clase química y la aplicación clínica de cada compuesto.'),
  (317, 'La primera afirmación es falsa porque el modelo farmacocinético no compartimental se emplea para describir la distribución y eliminación de fármacos que siguen un comportamiento lineal (proporcional a la concentración), no para aquellos con cinética no lineal; en los últimos se requiere un modelo que incluya saturación o procesos de saturación, como la cinética de Michaelis–Menten, y no el enfoque no compartimental. La segunda afirmación también es falsa porque la constante de Michaelis‑Menten (Km) no equivale a la mitad de la velocidad máxima (Vmax) de biotransformación; Km representa la concentración de fármaco a la que la velocidad de metabolismo alcanza la mitad de Vmax, pero no es una relación directa de equivalencia numérica. Por tanto, ambas afirmaciones son incorrectas, lo que hace que la opción D sea la única que coincide con la realidad farmacocinética.'),
  (318, 'Para fármacos con índice terapéutico alto y semivida corta, la frecuencia de administración debe ser mayor que la semivida para evitar fluctuaciones de concentración que, aunque el margen terapéutico sea amplio, podrían producir efectos colaterales o pérdida de eficacia; por ello la pauta óptima es de 3 a 6 veces la semivida, garantizando una exposición constante y evitando picos y valles. Las otras opciones son insuficientes: la opción B (2 veces la semivida) no cubre adecuadamente la rápida eliminación, la C (1 semivida) permite que la concentración caiga por debajo del nivel terapéutico entre dosis, y la D (<1 semivida) implicaría una frecuencia excesiva sin beneficio adicional, ya que el margen terapéutico no justifica tal régimen.'),
  (319, 'La vía intramuscular presenta una fase de absorción porque el fármaco se introduce en el tejido muscular, donde la perfusión sanguínea permite que el fármaco se disuelva en el intersticio y luego se difunda a través de las membranas capilares hacia el torrente sanguíneo, generando un perfil de concentración que aumenta gradualmente; en contraste, las vías intravenosa, intraarterial e intracardiaca introducen el fármaco directamente en la circulación sistémica o arterial, por lo que la concentración plasmática se alcanza de inmediato y no hay fase de absorción, sino distribución y eliminación; por tanto, la única opción que contempla una fase de absorción es la intramuscular.'),
  (320, 'La afirmación A es cierta porque la profundidad de penetración de las partículas inhaladas depende de su tamaño y densidad: partículas más pequeñas y menos densas poseen mayor capacidad de llegar a los bronquiolos y alveolos, mientras que partículas más grandes se depositan en las vías aéreas superiores; por tanto, la penetración es inversamente proporcional al tamaño y densidad. La opción B es incorrecta porque el ritmo respiratorio no determina directamente la profundidad de penetración; la distribución depende del tamaño de partícula y la dinámica de flujo, no de la frecuencia respiratoria. La opción C es errónea porque la vía pulmonar evita el primer paso hepático, ya que el fármaco se absorbe directamente en la sangre pulmonar y entra al sistema circulatorio sistémico sin pasar por el hígado. La opción D es falsa porque la absorción pulmonar suele ser rápida, con un pico de concentración plasmática alcanzado en minutos, no lenta.'),
  (321, 'El volumen de distribución (Vd) se define como la relación entre la cantidad total de fármaco en el organismo y su concentración plasmática; por ello su valor está determinado por la capacidad del fármaco para difundirse fuera del compartimento vascular y por la fracción de fármaco libre que puede unirse a proteínas plasmáticas y a los tejidos, de modo que la opción B es la única que refleja correctamente este mecanismo farmacocinético, ya que la fracción libre es la que participa en la distribución y el Vd aumenta cuando mayor es la proporción de fármaco libre que se desplaza a los tejidos. Las demás alternativas son erróneas: la opción A presupone una limitación física inexistente, pues el Vd puede superar el volumen de agua corporal cuando el fármaco se acumula en tejidos lipídicos; la opción C es falsa porque el coeficiente de reparto (Kd) entre plasma y tejidos es un factor que condiciona la distribución y, por tanto, el Vd; la opción D es incorrecta porque la extravasación facilita la entrada del fármaco al espacio intersticial, incrementando el Vd, no reduciéndolo.'),
  (322, 'La biodisponibilidad se define como la fracción de la dosis administrada que llega al torrente sistémico en forma activa; para cuantificarla se compara la exposición total al fármaco tras administración oral con la de una vía de referencia (por ejemplo, intravenosa). El parámetro que refleja esa exposición total es la integral de la curva concentración‑tiempo (AUC), ya que incorpora tanto la fase de absorción como la de eliminación, y es independiente de la forma de la curva; por ello la opción C es la que se emplea. La concentración máxima (Cmax) solo indica el pico de concentración y no la cantidad total de fármaco que circula; la concentración en equilibrio dinámico (Css) solo es relevante en régimen de mantenimiento y no describe la exposición inicial; y el área bajo el primer tramo de la curva (opción D) no cubre la totalidad de la eliminación, por lo que no permite calcular la biodisponibilidad.'),
  (323, 'La dosis de bolus necesaria para alcanzar rápidamente un nivel plasmático objetivo en una perfusión continua se calcula como el producto de la concentración deseada en equilibrio dinámico (Cₑq) por el volumen de distribución (Vd), es decir, D = Cₑq × Vd; el volumen de distribución determina cuánta molécula se necesita para llenar el compartimento fisiológico y la concentración de equilibrio indica el nivel que se mantendrá con la perfusión; la semivida de eliminación no interviene en el cálculo de la dosis inicial, sino en la determinación de la tasa de perfusión que mantendrá el nivel, mientras que el área bajo la curva (AUC) describe la exposición total y no la dosis puntual. Por tanto, la opción A es la única que incluye los dos parámetros esenciales; las demás opciones incluyen el volumen de distribución pero añaden la semivida plasmática o el AUC, que no son necesarios para fijar la dosis de bolus inicial.'),
  (324, 'El fenómeno flip‑flop ocurre cuando la velocidad de absorción (ka) es más lenta que la velocidad de eliminación del fármaco; en un modelo bicompartimental la eliminación se describe por las constantes α (fase rápida) y β (fase lenta), y la tasa de eliminación efectiva es la más lenta, β, por lo que la condición para flip‑flop es α > β > ka, es decir, la constante de absorción es la más pequeña y la fase lenta domina la eliminación; las demás opciones presentan la relación de constantes incorrecta, ya que en B y C la constante de absorción se sitúa entre α y β o mayor que β, y en D la constante de absorción es mayor que β, por lo que no se cumple la condición de que la eliminación sea más rápida que la absorción.'),
  (325, 'Para un fármaco monocompartimental con eliminación de primer orden, la concentración plasmática disminuye a la mitad cada semivida; por lo tanto, después de n semividas la concentración será (1/2)^n de la inicial, y para alcanzar la octava parte (1/8) se necesita (1/2)^3, es decir, tres semividas de eliminación; la opción C refleja esa relación; las demás alternativas fallan porque asumen un número de semividas menor (B) o mayor (A y D) que no satisface la ecuación (1/2)^n = 1/8, por lo que no conducen a la reducción deseada.'),
  (326, 'La concentración plasmática en estado estacionario (Css) para un fármaco de eliminación de orden uno se determina por la relación Css = (F·Dose)/(Cl·τ) o, en el caso de perfusión continua, Css = (Rate_in)/Cl. Dado que la velocidad de perfusión inicial es de 10 mg h⁻¹ y se alcanza una Css de 40 mg L⁻¹, se puede inferir que la eliminación (Cl) es constante y que la relación entre la tasa de entrada y la concentración es lineal. Al aumentar la velocidad de perfusión a 40 mg h⁻¹, la concentración plasmática en equilibrio aumentará proporcionalmente, pues la eliminación sigue siendo de primer orden y la tasa de entrada se incrementa cuatro veces. Por lo tanto, la nueva concentración será 40 mg L⁻¹ × 4 = 160 mg L⁻¹, que corresponde a la opción D. Las opciones A, B y C son incorrectas porque no reflejan la proporcionalidad lineal entre la tasa de perfusión y la concentración plasmática en estado estacionario para un fármaco de orden uno; la opción A sugiere una relación inversa, la B mantiene la misma concentración pese a un aumento de la tasa, y la C solo duplica la concentración cuando la tasa se cuadruplica.'),
  (327, 'La bioexención solo se aplica a los medicamentos de clase I del Sistema de Clasificación Biofarmacéutico, es decir, aquellos cuya biodisponibilidad oral es inferior al 30 % y que presentan una variabilidad interindividual alta; por ello el medicamento debe presentarse en forma de comprimido de liberación inmediata para que el organismo pueda absorber la dosis completa en el menor tiempo posible y evitar la variabilidad, lo que es el caso del antihipertensivo de clase I en comprimidos de liberación inmediata (opción D). En cambio, la opción A describe un vasodilatador coronario de clase III, cuya biodisponibilidad es alta y la variabilidad baja, por lo que no requiere bioexención; la opción B se refiere a un antiparkinsoniano de clase III, también con biodisponibilidad elevada, y la opción C menciona un antipsicótico de clase I pero en forma de liberación prolongada, la cual aumenta la variabilidad y la exposición total, por lo que tampoco se considera objeto de bioexención.'),
  (328, 'La síntesis de fosfolípidos no nitrogenados, como el fosfatidilinositol (PI), se inicia con la activación del diacilglicerol (DAG) mediante la enzima CDP‑diacilglicerol sintasa, que produce CDP‑diacilglicerol (CDP‑DAG); este compuesto actúa como sustrato donante de la cabeza inositol, que se une a través de la reacción catalizada por la inositol‑phosphate acyltransferasa, generando PI; por lo tanto, la opción A es la que describe correctamente el par de reactivos (CDP‑diacilglicerol e inositol) que participan en la condensación. Las demás alternativas son incorrectas porque la reacción no involucra directamente diacilglicerol sin activación (B), ni CDP‑inositol (C), ni inositol‑fosfato (D), que no son los sustratos que se condensan con CDP‑diacilglicerol en la vía de síntesis de PI.'),
  (329, 'La afirmación correcta es la B porque el malonil‑CoA, producto de la acetil‑CoA carboxilasa, actúa como un inhibidor de la β‑oxidación al competir con el acil‑CoA por la acil‑CoA deshidrogenasa, reduciendo la velocidad de la reacción de oxidación de los ácidos grasos; en la lipogénesis, por el contrario, el malonil‑CoA es el sustrato que se añade al acetil‑CoA para formar el primer intermediario de la cadena, por lo que su presencia favorece la síntesis de ácidos grasos. En la opción A se confunde la unión de los intermediarios: en la β‑oxidación los acil‑CoA son activados por la ACP (ácido palmítico‑ACP) y en la lipogénesis los intermediarios están unidos a CoA, pero la afirmación no refleja la diferencia entre las dos rutas. La opción C presenta un error sobre los cofactores: la β‑cetoacil‑reductasa utiliza NADPH, no NADH, y la 3‑L‑hidroxiacil‑CoA deshidrogenasa utiliza NAD⁺, no NADPH. La opción D es incorrecta porque la última reacción de la β‑oxidación es la deshidrogenación del acil‑CoA por la acil‑CoA deshidrogenasa, mientras que en la lipogénesis la última reacción es la reducción del malonil‑CoA a acil‑CoA por la malonil‑CoA reductasa, no la palmitoil‑tioesterasa.'),
  (330, 'El acetil‑CoA actúa como inhibidor allostérico de la piruvato deshidrogenasa; al bloquear la conversión de piruvato en acetil‑CoA, aumenta la concentración de piruvato que puede ser convertido en oxalacetato por la piruvato carboxilasa, el primer paso de la gluconeogénesis, por lo que la opción C describe el mecanismo fisiológico correcto. La opción A es errónea porque la piruvato quinasa no participa en la gluconeogénesis y la fosfoenolpiruvato carboxiquinasa se regula por el ATP y el citrato, no por el acetil‑CoA; la opción B es incorrecta porque la hexoquinasa actúa en la glucólisis y la malato deshidrogenasa no está directamente implicada en el control del flujo gluconeogénico; la opción D es falsa porque la lactato deshidrogenasa convierte lactato en piruvato y la glucosa‑6‑fosfatasa actúa en la glucosa‑6‑fosfato, no en el paso regulado por el acetil‑CoA.'),
  (331, 'Los complejos enzimáticos de la piruvato deshidrogenasa (PDH) y de la α‑cetoglutarato deshidrogenasa (α‑KGDH) comparten la necesidad de los mismos cofactores esenciales: el pirofosfato de tiamina (TPP), el lipoato (en forma de lipoil‑CoA), la coenzima A (CoA), la flavina adenina dinucleótido (FAD) y el nicotinamida adenina dinucleótido oxidado (NAD+); estos componentes participan en la transferencia de electrones y en la formación de acetil‑CoA o succinil‑CoA, respectivamente, y son imprescindibles para la actividad catalítica de ambos complejos. En contraste, la opción A es incorrecta porque, aunque ambos complejos catalizan reacciones de deshidrogenación, el PDH produce acetil‑CoA mientras que el α‑KGDH produce succinil‑CoA, por lo que la afirmación de una única molécula de acetil‑CoA no es válida. La opción B es errónea porque un alto cociente [NADH]/[NAD+] inhibe la actividad de estos complejos, no la potencia. La opción C es falsa porque, si bien las reacciones son exergónicas y generan NADH, no se produce ATP directamente; el ATP se forma en etapas posteriores del ciclo de Krebs o en la fosforilación oxidativa.'),
  (332, 'La biocitina es el cofactor que se une covalentemente a la enzima carboxilasa de la acetil-CoA carboxilasa, permitiendo la transferencia de un grupo carboxilo a la acetil-CoA para formar malonil-CoA, y por tanto participa en reacciones de carboxilación; las otras opciones son inexactas porque la coenzima A participa en reacciones de transferencia de grupos acilo, no de alquilación; el pirofosfato de tiamina es el cofactor de la transpiridilación, no de transferencias acilo; y la piridoxal fosfato actúa como cofactor de transaminasas y otras enzimas que transfieren grupos amino, no grupos aldehído.'),
  (333, 'La síntesis de δ‑aminolevulinato (ALA) es el primer paso de la vía de la porfirina, en la que el succinil‑CoA y la glicina se combinan mediante la enzima ALA‑sintasa; este producto es el precursor directo de la uroporfirina IX y, por ende, de todas las porfirinas, pigmentos esenciales para la hemoglobina, la mioglobina y los citocromos; las prostaglandinas se forman a partir de ácidos grasos, los gangliósidos son glicoconjugados de lípidos y los plasmalógenos son lípidos de membrana, por lo que las opciones A, B y D describen rutas bioquímicas distintas a la de la porfirina.'),
  (334, 'La opción B es la que describe correctamente el efecto de un inhibidor competitivo: el inhibidor se une al sitio activo de la enzima libre, compitiendo con el sustrato, y por ello la constante de Michaelis aparente aumenta según KM(ap) = α·KM, donde α > 1; la Vmax permanece inalterada porque, al aumentar la concentración de sustrato, se puede saturar la enzima y alcanzar la velocidad máxima. La alternativa A es incorrecta porque el inhibidor competitivo no afecta la Vmax; la disminución de la velocidad máxima se observa con inhibidores no competitivos o de tipo mixto. La opción C describe un inhibidor no competitivo o de tipo mixto, que se une al complejo enzima‑sustrato y altera la actividad catalítica sin cambiar la interacción inicial entre enzima y sustrato. La alternativa D mezcla características de inhibidores mixtos y no competitivos, pues afirma que el inhibidor interactúa indistintamente con la enzima libre y el complejo, reduciendo simultáneamente Vmax y KM, lo cual no ocurre en la inhibición competitiva.'),
  (335, 'El 2,4‑dinitrofenol es un desacoplante que actúa como protonoporo, transportando protones a través de la membrana interna mitocondrial y disipando el gradiente electroquímico; al permitir que los protones regresen a la matriz sin pasar por la ATP sintasa, se interrumpe la generación de ATP a partir del potencial de protones, por lo que la opción A describe correctamente su mecanismo. La opción B es incorrecta porque el 2,4‑dinitrofenol no interfiere con el citocromo A ni con la cadena de transporte de electrones; su acción se limita a la membrana y no bloquea la reducción de O₂. La alternativa C también es falsa, ya que el desacoplante no se une a la subunidad Fo de la ATP sintasa ni impide la formación del enlace fosfoanhídrido; simplemente evita que el gradiente de protones genere la fuerza motriz necesaria para la síntesis de ATP. Finalmente, la respuesta D es errónea porque el 2,4‑dinitrofenol no introduce electrones en la matriz ni produce radicales superóxido; su efecto es la pérdida del gradiente de protones sin generar especies reactivas de oxígeno.'),
  (336, 'Los aminoácidos cetogénicos, como la leucina y la lisina, contienen cadenas de carbono que, al ser catabolizadas, generan acetil‑CoA, el cual se dirige al ciclo de los ácidos tricarboxílicos y a la síntesis de cuerpos cetónicos; por tanto la opción D es la única que refleja la vía metabólica de estos aminoácidos. Las demás alternativas son inadecuadas: la opción A sugiere la formación de glutamato, que corresponde a aminoácidos no cetogénicos que se desaminan a través de la transaminación; la B indica propionil‑CoA, típica de aminoácidos no cetogénicos y no cetogénicos que producen cuerpos cetónicos; y la C menciona succinil‑CoA, que deriva de aminoácidos que alimentan el ciclo de Krebs pero no generan cuerpos cetónicos.'),
  (337, 'La respuesta es la opción B porque la glucólisis muscular se regula por tres enzimas catalizadoras de reacciones irreversibles: la hexoquinasa (o glucocinasa en hígado) que fosforila la glucosa a glucosa‑6‑fosfato; la fosfofructoquinasa‑1, que convierte la fructosa‑6‑fosfato en fructosa‑1,6‑bisfosfato; y la piruvato quinasa, que forma piruvato a partir de fosfoenolpiruvato; estas tres son las únicas que controlan el flujo de la vía y son irreversibles en el contexto muscular. La opción A menciona la gliceraldehído‑3‑fosfato deshidrogenasa, que es reversible y no regula la vía; la opción C incluye fosfoglicerato quinasa y enolasa, enzimas que también son reversibles y no determinan el paso de control; la opción D sustituye la hexoquinasa por glucoquinasa, que no se expresa en músculo y, además, la fosfoglicerato quinasa no es una enzima irreversiblemente reguladora de la glucólisis.'),
  (338, 'La hemoglobina con el ion ferroso oxidado a Fe³⁺ se llama metahemoglobina porque la oxidación del hierro a su estado férrico impide la unión del oxígeno y la molécula adquiere un espectro de absorción distinto, característico de la metahemoglobina; la oxidación irreversible del hierro a Fe³⁺ se produce por exposición a agentes oxidantes o por defectos en la enzima ferroxidasa, y el resultado es una forma inactiva que no transporta oxígeno. La opción A, oxihemoglobina, describe la hemoglobina con hierro Fe²⁺ ligada al oxígeno; la B, hemoglobina S, es la variante con mutación de la cadena β que causa la sickle cell; la D, hemoglobina reducida, se refiere a la forma Fe²⁺ sin oxígeno. Todas las demás alternativas describen estados o variantes distintas a la metahemoglobina.'),
  (339, 'La fermentación tiene como objetivo principal regenerar el cofactor NAD⁺ oxidado a partir de NADH producido durante la glicólisis, permitiendo que la vía siga funcionando en ausencia de oxígeno; por tanto la opción D describe la función metabólica esencial de este proceso. Las demás alternativas son inexactas: la fermentación no consume CO₂ (opción A), pues en la mayoría de los tipos de fermentación el CO₂ se libera como subproducto, no se consume; no genera productos de desecho que se puedan eliminar (opción B), ya que los productos finales son metabolitos que pueden ser reutilizados o excretados, pero no se definen como “desperdicios” eliminables; y no convierte los azúcares en acetato y compuestos derivados de él (opción C), pues esa descripción corresponde a la respiración aeróbica o a la fermentación láctica, no a la función regenerativa del NAD⁺.'),
  (340, 'Los quilomicrones son lipoproteínas de muy baja densidad que se sintetizan en el enterocito intestinal a partir de los triglicéridos y fosfolípidos de la dieta; su transporte se realiza a través del sistema linfático y luego al torrente sanguíneo, donde liberan ácidos grasos a los tejidos periféricos, especialmente a músculo y tejido adiposo, mediante la acción de la lipoproteína lipasa; por tanto la opción B describe el proceso fisiológico correcto, mientras que la A implica un flujo hepático que corresponde a VLDL, la C describe la ruta de la VLDL que lleva lípidos del hígado a tejidos, y la D invierte la dirección de transporte, lo cual no ocurre con los quilomicrones.'),
  (341, 'La línea hereditaria materna se transmite exclusivamente a través del ADN mitocondrial, que se hereda de la madre y no se mezcla con el ADN nuclear durante la fertilización, por lo que los marcadores de ADN mitocondrial permiten rastrear la ascendencia materna de manera específica; el pseudogén es un fragmento de ADN que no codifica proteínas y no refleja la herencia lineal; el centrómero es una región estructural del cromosoma que no contiene información hereditaria específica de la madre; el ARN de transferencia es un componente del ribosoma que participa en la traducción y tampoco se hereda de forma lineal, por lo que las opciones A, B y D no permiten investigar la línea materna.'),
  (342, 'La secuencia que se encuentra en el gen pero no en el ARN mensajero maduro es el intrón, ya que durante el procesamiento del pre‑ARNm se eliminan los segmentos no codificantes mediante el spliceosoma, dejando únicamente los exones que forman el ARNm funcional; el promotor es una región reguladora situada 5′ del gen y no forma parte del ARN, mientras que el intensificador (enhancer) es un elemento regulador distal que también no se transcribe, por lo que ni el promotor ni el intensificador son parte del ARN maduro, pero la pregunta se centra en la secuencia que se elimina del gen, identificándose correctamente al intrón.'),
  (343, 'Las helicasas son enzimas que, mediante la hidrólisis de ATP, generan la energía necesaria para desenrollar y separar las hebras de los ácidos nucleicos, acción esencial durante la replicación y transcripción; por tanto la afirmación B es la única que describe correctamente su función, mientras que la opción A confunde su actividad con la modificación de la estructura cuaternaria del ARN, algo que no realizan; la C describe una unión a ADN de cadena sencilla, que corresponde a proteínas de unión a ssDNA pero no a la función de separación de hebras; y la D atribuye a las helicasas un papel de unión al ADN, cuando su función principal es la separación de las hebras, no la simple unión.'),
  (344, 'Un transposón es una secuencia de ADN que posee la capacidad de replicarse y de insertarse en un sitio distinto del genoma, ya sea mediante un mecanismo de copia-pegado (retrotransposón) o de corte-pegado (transposón de ADN), lo que explica la movilidad intrínseca de estos elementos y su papel en la variabilidad genética; por tanto la opción D describe fielmente esa característica. Las demás alternativas son inexactas: la A confunde el transposón con un plásmido bacteriano, que es un círculo extracromosómico distinto; la B se refiere a una mutación por desfase, que no implica movilidad; y la C menciona un “cósmido” (un plasmidio modificado para clonación) que no tiene relación con la transposición.'),
  (345, 'El enlace disulfuro que se forma entre dos cadenas polipeptídicas constituye una unión covalente que mantiene la conformación tridimensional de la proteína, por lo que se considera parte de su estructura terciaria; la estructura primaria se limita a la secuencia de aminoácidos, la secundaria a patrones de plegamiento local como hélices alfa y láminas beta, y la cuaternaria describe la asociación de múltiples subunidades proteicas, no la formación de enlaces entre residuos de la misma cadena; las opciones A y B son erróneas porque el enlace disulfuro no determina la secuencia lineal ni los patrones de plegamiento local, y la opción D es incorrecta porque la unión no implica la asociación de distintas subunidades.'),
  (346, 'Las mutaciones sin sentido son sustituciones nucleotídicas que transforman un codón codificante en uno de parada (UAA, UAG o UGA), provocando la terminación prematura de la síntesis polipeptídica y la producción de una proteína truncada; por ello la opción C es la única que describe correctamente el efecto de este tipo de mutación. La opción A se refiere a mutaciones de marco de lectura, que implican inserciones o deleciones de nucleótidos y alteran el desplazamiento de los codones, no sustituciones que introducen terminaciones; la B describe una mutación de sentido, donde el codón sigue codificando un aminoácido distinto, y la D corresponde a una mutación de sentido que cambia un aminoácido por otro químicamente análogo, tampoco aplicable a las sin sentido.'),
  (347, 'Los genes truncados se definen como copias incompletas de un gen original, resultantes de la pérdida de una región situada en uno de los extremos, ya sea 5’ o 3’, lo que impide la síntesis completa de la proteína codificada y suele generar una forma funcionalmente alterada o inactiva; por tanto la opción A describe con precisión la característica esencial de estos genes, mientras que la opción B confunde truncados con genes de baja homología, que no implica necesariamente truncamiento; la opción C asocia erróneamente los genes truncados con regiones repetitivas, pues la repetición no es un requisito de truncamiento; y la opción D sugiere que son genes agrupados, lo cual se refiere a la organización cromosómica y no a la pérdida de regiones.'),
  (348, 'En la síntesis de ADN recombinante, el vector de clonaje debe ser una molécula de ADN que pueda replicarse dentro de una célula huésped y que permita la inserción de fragmentos de ADN de interés; los plásmidos bacterianos, los fagos y los cromosomas de levadura (plásmidos de levadura) cumplen con estas características, por lo que la opción B es la única que describe correctamente los posibles vectores de clonaje. La opción A es incorrecta porque la unión de fragmentos de enzimas no es un requisito para la síntesis de ADN recombinante; la enzima clave es la ADN polimerasa o la ligasa, no fragmentos de enzimas. La opción C es falsa porque el vector de clonaje debe ser de ADN; el ARN no puede replicarse ni integrarse en el genoma de forma estable en la mayoría de los sistemas de clonación. La opción D es errónea porque el ADN recombinante no es sinónimo de ADN complementario; el primero se refiere a una molécula que contiene fragmentos de ADN provenientes de distintas fuentes, mientras que el complementario es simplemente la hebra opuesta a una cadena de ADN.'),
  (349, 'El sistema de reparación de mismatches actúa sobre las bases incorrectamente emparejadas que quedan tras la síntesis de la cadena complementaria durante la replicación del ADN, detectando y removiendo la hebra defectuosa mediante excisión y re-sintetizando la secuencia correcta; por tanto la opción C es la que describe el proceso; las alternativas A y B se refieren a daños que generan rupturas o modificaciones químicas del ADN que son reparados por otras vías (reparación por excisión de bases y reparación por excisión de nucleótidos), mientras que la D describe un proceso de recombinación que no implica la corrección de errores de emparejamiento.'),
  (350, 'La alanina aminotransferasa (ALT) es una enzima citosólica que se libera principalmente en la sangre cuando hay lesión hepática o muscular; su concentración se ve alterada en ejercicios de alta intensidad que provocan daño miofibrilar, pero en la práctica clínica y en estudios de fisiología del ejercicio se observa que la ALT no presenta un aumento significativo tras una sesión de ejercicio intenso, a diferencia de la creatina cinasa (CK), que aumenta de forma marcada por la liberación de mioglobina y daño muscular, la lactato deshidrogenasa (LDH), que se eleva con la ruptura de células musculares y la producción de lactato, y los leucocitos, cuyo conteo aumenta por la movilización de la respuesta inflamatoria y el estrés fisiológico; por lo tanto, la opción D es la única que no se ve modificada, mientras que las demás opciones se alteran por el daño y la respuesta inmunológica inducida por el ejercicio.'),
  (351, 'La opción B es la que presenta la información errónea: la deficiencia de yodo provoca hipotiroidismo, no hipertiroidismo, porque el yodo es esencial para la síntesis de las hormonas tiroideas T3 y T4, y su carencia reduce la producción de estas, produciendo un aumento del TSH y síntomas de hipotiroidismo; la hipertiroidismo se asocia con exceso de yodo o enfermedad de Graves. Las demás opciones son correctas: la espectrometría de absorción atómica (A) es una técnica de referencia para cuantificar trazas; la deficiencia de zinc (D) sí causa alteraciones inmunológicas, lesiones cutáneas y alopecia; y la presencia de hemólisis (C) interfiere con la determinación de hierro, zinc y manganeso, por lo que las muestras hemolizadas deben evitarse.'),
  (352, 'La hipopotasemia no es característica de la insuficiencia renal aguda; en ese contexto la retención de potasio suele provocar hiperkalemia, ya que la excreción renal de K⁺ se reduce; por tanto la opción D es la que no concuerda con la fisiopatología renal. En la diabetes insípida nefrogénica la resistencia a la ADH provoca una pérdida de agua que lleva a hipernatremia hipovolémica, por lo que la opción A es coherente. El síndrome de secreción inadecuada de hormona antidiurética (SIADH) se caracteriza por exceso de ADH y, por ende, retención de agua con dilución sérica, resultando en hiponatremia, lo que valida la opción B. El hiperaldosteronismo aumenta la excreción de potasio en la orina, causando hipopotasemia, de modo que la opción C también es correcta. Las opciones A, B y C están fundamentadas en los mecanismos fisiológicos típicos de cada síndrome, mientras que la D se contradice con la fisiopatología de la insuficiencia renal aguda.'),
  (353, 'La piridolina (o piridoxina, vitamina B6) no participa en la síntesis de matriz ósea ni en la mineralización, por lo que no se considera un marcador de formación ósea; en cambio, la fosfatasa alcalina ósea, la osteocalcina y el propéptido N‑terminal del colágeno tipo I son proteínas y fragmentos de colágeno que se liberan durante la osteogénesis y la mineralización, reflejando la actividad de los osteoblastos. Las opciones A, B y D son marcadores de formación ósea porque su presencia en suero o orina aumenta con la actividad osteoblástica, mientras que la opción C corresponde a una vitamina esencial para el metabolismo de aminoácidos y la síntesis de neurotransmisores, no a un componente de la matriz ósea.'),
  (354, 'La tirotropina (TSH) no participa en la contrarregulación de la insulina porque su función principal es estimular la síntesis y liberación de hormonas tiroideas, las cuales modulan el metabolismo basal pero no tienen un efecto directo sobre la sensibilidad a la insulina ni sobre la secreción de esta; en cambio, la adrenalina, el cortisol y el lactógeno placentario son hormonas glucagónicas que, mediante la activación de sus respectivos receptores G‑s, aumentan la producción de AMP‑c y la fosforilación de proteínas clave, elevando la glucosa plasmática y reduciendo la captación de glucosa por los tejidos, por lo que actúan como contrarreguladores de la insulina. Las opciones A, B y C comparten este mecanismo glucagónico, mientras que la D difiere por su función endocrina distinta.'),
  (355, 'La apolipoproteína (a) posee una secuencia de dominios de tipo kringle idénticos a los que se encuentran en el plasminógeno, lo que le confiere una conformación tridimensional muy parecida y la capacidad de unirse a la fibrina; sin embargo, carece de la región peptidálica que codifica la serina proteasa, por lo que no exhibe actividad enzimática, a diferencia del plasminógeno que sí lo posee. Las demás apolipoproteínas (E, AI y CII) no presentan dominios kringle ni una estructura semejante al plasminógeno; E y AI están compuestas principalmente por hélices alfa y CII es una proteína pequeña que actúa como cofactor activador de la trombina, por lo que no comparten la similitud estructural ni la ausencia de actividad enzimática que caracteriza a la (a).'),
  (356, 'La constante de formación condicional (Kf, c) se emplea en la química de coordinación para cuantificar la estabilidad de un complejo metal‑ligando bajo condiciones específicas de concentración y pH; por ello se relaciona directamente con la formación de complejos, ya que describe la equilibración entre el metal libre y el ligando en presencia de un agente quelante, y permite comparar la afinidad relativa de distintos ligandos por el mismo centro metálico. Las opciones A y B se refieren a procesos ácido‑base y de precipitación, que se describen mediante constantes de disociación (pKa) y solubilidad (Ksp), respectivamente, y no involucran la formación de enlaces coordinados; la opción C, aunque también involucra reacciones redox, utiliza potenciales de reducción y no constantes de formación condicionales, por lo que las tres alternativas restantes son incorrectas.'),
  (357, 'El reductor de Jones es una solución de zinc amalgamado con cloroformo que actúa como agente de reducción fuerte, proporcionando 2 electrones por átomo de zinc y generando una corriente de 0,76 V, lo que permite oxidar a los compuestos de interés en las valoraciones de óxido‑reducción; el zinc metálico se oxida a Zn²⁺ mientras que el cloroformo se mantiene estable, y la amalgama facilita la difusión del metal y evita la formación de óxidos superficiales que reducirían la potencia; la opción A (sulfato ferroso amónico) es un reductor de hierro que no alcanza el potencial requerido, la B (tiosulfato de sodio) es un agente oxidante y la C (cloruro de plata) es un reactivo de precipitación, no un reductor; por tanto, solo la D corresponde a la composición del reductor de Jones.'),
  (358, 'La estandarización de una disolución de permanganato de potasio se realiza con un patrón primario que sea sólido, estable, de pureza conocida y que reaccione de forma completa con el permanganato en un medio ácido; el oxalato de sodio cumple exactamente estos requisitos, ya que es un sólido cristalino de alta pureza, se disuelve fácilmente y su reacción con KMnO₄ en ácido clorhídrico es una valoración de óxido‑reducción bien establecida con un número de equivalentes fijo (2 e⁻ por molécula de oxalato). El nitrato de amonio y cerio (IV) no es un patrón estándar, pues su pureza y estabilidad no están garantizadas y su reacción con KMnO₄ no es de uso habitual; el bismutato de sodio es un compuesto ácido que no reacciona con el permanganato en ácido, y el sulfato de etilendiamina es un agente quelante que tampoco sirve como patrón de valoración de óxido‑reducción.'),
  (359, 'El dihidrógeno fosfato de sodio (H₂PO₄⁻) es la forma de ácido débil que corresponde al segundo paso de disociación del ácido fosfórico (pKa₂ = 7,21). En una solución 0,01 M de H₂PO₄⁻, la concentración de su base conjugada (HPO₄²⁻) se genera por la reacción de equilibrio H₂PO₄⁻ ⇌ H⁺ + HPO₄²⁻, cuyo Ka₂ es 10⁻⁷,21 ≈ 6,2 × 10⁻⁸. Aplicando la expresión de equilibrio para un ácido débil, [H⁺] ≈ √(Ka₂ C) = √(6,2 × 10⁻⁸ × 0,01) ≈ 2,5 × 10⁻'),
  (360, 'La sensibilidad de un método analítico se define como la capacidad de distinguir cambios pequeños en la concentración de analito, y se cuantifica mediante la pendiente de la recta de calibrado (opción C), ya que la pendiente indica cuántos puntos de respuesta se obtienen por unidad de concentración, reflejando directamente la respuesta del sistema frente a variaciones mínimas; las demás opciones son inadecuadas porque el coeficiente de variación (A) mide la reproducibilidad, el error relativo (B) evalúa la exactitud, y la ordenada en el origen (D) representa la interferencia o el ruido de fondo, ninguno de los cuales describe la sensibilidad.'),
  (361, 'En la valoración de Fe(II) con dicromato de potasio el punto final se detecta por la aparición de una corriente eléctrica que indica la completa reducción del dicromato a dicromato de hierro; para ello se emplea una pila electroquímica con un electrodo indicador de platino, que actúa como ánodo donde se produce la oxidación de Fe(II) y un electrodo de referencia que mantiene el potencial estable, de modo que la caída de potencial se registra cuando el dicromato se ha agotado; la elección del electrodo de platino garantiza una superficie estable y no reactiva con el reactivo, permitiendo una medición precisa del potencial. La opción A es incorrecta porque la murexida no es un indicador redox sino un agente quelante, no detecta el punto final. La opción B es errónea porque un electrodo de Fe como indicador sería reactivo con el analito y alteraría la medición. La opción D es inadecuada porque el engrudo de almidón se utiliza en titraciones de hierro con reactivos que forman complejos de almidón, no con dicromato de potasio.'),
  (362, 'El uso de disolventes halogenados como el diclorometano reduce la señal de fluorescencia porque favorece la relajación no radiativa a través de mecanismos de quenching interno, en los que la energía excitada se disipa en forma de vibraciones del solvente; este fenómeno se conoce como quenching por solvente y se debe a la alta polaridad y capacidad de interacción del diclorometano con el estado excitado del fluoróforo, lo que incrementa la probabilidad de relajación vibracional y disminuye la emisión luminosa. Las opciones A y C son erróneas porque asumen un aumento de la señal, lo cual no ocurre en presencia de solventes halogenados que favorecen la quenching; la opción D, aunque menciona la disminución, atribuye el efecto a la conversión externa, un proceso distinto que no explica la interacción específica del diclorometano con el estado excitado.'),
  (363, 'La altura equivalente del plato teórico (H) se describe por la ecuación de Van Deemter: H = A + B/u + C · u, donde A representa la dispersión de eddies, B la difusión en la fase móvil y C la transferencia de masa entre fases; el término A aumenta directamente con el diámetro de partícula de la fase estacionaria porque mayor tamaño genera mayor número de caminos y mayor dispersión de eddies, por lo que la opción A es la que provoca el incremento de H. Las demás alternativas son incorrectas: la reducción del diámetro interno de la columna (B) afecta principalmente a la resistencia al flujo y a la velocidad de transporte, pero no a la dispersión de eddies; la disminución del espesor del recubrimiento líquido (C) influye sobre la fase estacionaria y la transferencia de masa (término C), no sobre el término A; y el aumento del coeficiente de difusión del soluto en la fase estacionaria (D) se relaciona con el término B, no con la dispersión de eddies.'),
  (364, 'La ionización química (CI) emplea iones gaseosos reactivos, típicamente iones de metano o etano, que colisionan con las moléculas de la muestra en fase gaseosa y provocan su ionización mediante procesos de transferencia de carga o de reacción química, lo que permite obtener iones de la molécula objetivo con alta eficiencia y menor fragmentación; por ello es la única de las opciones que utiliza iones gaseosos reactivos para la obtención de iones. Las otras alternativas corresponden a técnicas de ionización por impacto de electrones (EI), que generan iones mediante colisiones de electrones de alta energía, y a la desorción/ionización por láser asistida con matriz (MALDI), que emplea un láser para desorber y ionizar la muestra sin usar iones reactivos; la opción B, el bombardeo por átomos rápidos, también se basa en colisiones de átomos energizados, no en iones reactivos.'),
  (365, 'El parámetro que permanece invariable es la frecuencia; al pasar de un medio a otro la frecuencia de la onda electromagnética no cambia porque está determinada por la fuente emisora y no por el medio, mientras que la velocidad se ajusta al índice de refracción, la longitud de onda se reduce proporcionalmente y el número de onda aumenta, por lo que las opciones B, C y D describen parámetros que sí varían con el medio.'),
  (366, 'La antorcha ICP-AES consiste en tres tubos concéntricos, el tubo interno de argón que genera la llama de plasma, el tubo intermedio de aire que mantiene la temperatura y el tubo externo de argón que protege el plasma; por tanto la opción B describe correctamente la configuración de la fuente de acoplamiento inductivo. Las demás alternativas son erróneas porque la antorcha no emplea un único tubo (A y C) ni utiliza aire‑hidrógeno (D), ya que el plasma se produce únicamente con argón y el aire se introduce en el segundo tubo para controlar la temperatura y la estabilidad del plasma.'),
  (367, 'El ensanchamiento de las líneas espectrales en espectrometría atómica cuando la temperatura aumenta se debe principalmente al efecto Doppler, que se intensifica con la velocidad térmica creciente de los átomos, y al ensanchamiento por presión (o colisión), que también aumenta con la densidad y la temperatura al incrementar la frecuencia de colisiones entre átomos y moléculas; ambos mecanismos dependen directamente de la energía cinética térmica. La opción B menciona el ensanchamiento natural, que es intrínsecamente limitado por la incertidumbre de tiempo de vida de los estados excitados y no varía con la temperatura; la opción C incluye el efecto Planck, que describe la distribución de energía de fotones y no contribuye al ancho de línea; la opción D combina ensanchamiento natural y Planck, ambos irrelevantes para el fenómeno térmico descrito.'),
  (368, 'En una valoración fotométrica donde la longitud de onda elegida hace que únicamente el titulador sea absorbente, la absorbancia medida corresponde directamente a la concentración de este reactivo añadido; por lo tanto, mientras se añada titulador antes del punto de equivalencia la absorbancia aumenta linealmente con el volumen titulado, y al alcanzar el punto de equivalencia la concentración de titulador queda constante, de modo que la absorbancia deja de crecer y permanece estable; por consiguiente, la opción B describe fielmente este comportamiento. Las demás alternativas son erróneas porque la opción A implica un crecimiento continuo, lo cual no ocurre una vez alcanzado el punto de equivalencia; la opción C sugiere que la absorbancia solo aumenta antes del punto de equivalencia, ignorando que también lo hace justo hasta ese momento; y la opción D afirma que la absorbancia no varía después del punto de equivalencia, lo cual es falso porque la absorbancia ya se ha estabilizado antes de ese punto.'),
  (369, 'El cloro molecular (Cl₂) es una molécula homonuclear diatómica con simetría lineal y centro de inversión; su vibración fundamental de estiramiento no produce un cambio en el momento dipolar, por lo que no es IR activa y no aparece en el espectro infrarrojo; la opción D refleja precisamente esta ausencia de absorción, mientras que las alternativas A, B y C describen bandas en regiones de frecuencia que corresponden a vibraciones de tensión o flexión de moléculas heteronucleadas o a la vibración de estiramiento de Cl₂, la cual, aunque está presente en el espectro Raman, no se observa en IR; por tanto, las opciones A, B y C son incorrectas porque atribuyen a Cl₂ bandas IR que en realidad no existen.'),
  (370, 'En cromatografía de gases, la utilización de una rampa de temperatura (gradiente) permite aumentar progresivamente la volatilidad de los compuestos a medida que la columna se calienta, lo que favorece la separación de analitos con puntos de ebullición muy distintos; los compuestos de baja volatilidad se retienen más tiempo en las etapas iniciales de la rampa, mientras que los de alta volatilidad se eluyen rápidamente cuando la temperatura alcanza niveles adecuados, logrando así una mayor resolución entre ellos. Las demás opciones son inadecuadas porque una rampa de temperatura no mejora la separación de analitos con puntos de ebullición muy semejantes (B), ya que ambos compuestos se comportan de manera similar a lo largo de la columna; tampoco es necesaria para analitos no volátiles, pues la cromatografía de gases requiere que los compuestos sean volátiles (C y D), por lo que la rampa no aportaría beneficios adicionales.'),
  (371, 'El detector de índice de refracción (D) es incompatible con la cromatografía líquida en gradiente porque la señal depende de la diferencia de índice entre el analito y el fase móvil, la cual varía de forma continua cuando el solvente cambia de composición; esto provoca una señal de fondo que no puede ser restablecida y dificulta la detección de picos, mientras que la absorbancia, la fluorescencia y los detectores electroquímicos dependen de propiedades intrínsecas del analito (absorción, emisión o corriente redox) que permanecen constantes a lo largo del gradiente, permitiendo su uso sin alteraciones de la señal de fondo. Por tanto, las opciones A, B y C son compatibles, y la única que presenta el error de incompatibilidad es la opción D.'),
  (372, 'La adición de un soluto no volátil y sin carga a un disolvente puro reduce la presión de vapor de la mezcla porque el soluto ocupa espacio intersticial y disminuye la fracción molar de las moléculas de disolvente que pueden escapar a la fase gaseosa; según la ley de Raoult, la presión de vapor de la disolución es el producto de la presión de vapor del disolvente puro por su fracción molar, por lo que el descenso es independiente de la naturaleza del soluto siempre que la solución sea ideal y el soluto no sea volátil. Por tanto la opción C es la única que refleja este comportamiento. La opción A es errónea porque, aunque el soluto no es volátil, su presencia sí altera la presión de vapor del disolvente. La opción B es incorrecta porque la variación no depende de la naturaleza del soluto en una solución ideal. La opción D es falsa porque la presión de vapor disminuye, no aumenta, cuando se añade un soluto no volátil.'),
  (373, 'La disminución de la temperatura de congelación depende de la concentración de partículas coligativas; cuanto mayor sea el número de moléculas disueltas por litro, mayor será la depresión del punto de congelación. Al convertir la concentración dada en g L⁻¹ a moles L⁻¹ se obtiene que la glucosa (180 g mol⁻¹) aporta 0,0056 mol L⁻¹, la sacarosa (342 g mol⁻¹) 0,0029 mol L⁻¹, la maltotriosa (504 g mol⁻¹) 0,0020 mol L⁻¹ y el glicerol (92 g mol⁻¹) 0,0109 mol L⁻¹. El glicerol, con la mayor cantidad de partículas por litro, provoca la mayor depresión del punto de congelación y por tanto la menor temperatura de congelación. Las demás opciones presentan menor número de moléculas disueltas y, en consecuencia, menores efectos coligativos; la glucosa, la sacarosa y la maltotriosa, al tener concentraciones molares inferiores, generan temperaturas de congelación más altas que la de glicerol.'),
  (374, 'La expresión t½=[A0]/(2k) muestra que el tiempo de semivida crece linealmente con la concentración inicial; en una cinética de orden cero la velocidad es constante (v=–k), por lo que la concentración disminuye linealmente con el tiempo y el tiempo necesario para que la concentración se reduzca a la mitad es directamente proporcional a A0, con la constante de proporcionalidad 1/(2k); en contraste, en cinética de primer orden t½=ln2/k, independiente de A0, y en segundo orden t½=1/(kA0), inversamente proporcional a A0, mientras que la expresión dada no coincide con ninguna de esas relaciones. Por tanto, la opción A describe la cinética observada; las demás opciones son incorrectas porque sus relaciones de semivida no dependen linealmente de la concentración inicial como se observa.'),
  (375, 'En un proceso a volumen constante el trabajo mecánico realizado por el sistema sobre su entorno es nulo, ya que la variación de volumen ΔV=0 y el trabajo de expansión se expresa como w=−PΔV; por lo tanto w=0 y la primera ley de la termodinámica ΔU=q+w reduce a ΔU=q, donde q es la energía térmica intercambiada a presión constante (q_v). La opción C refleja esta relación, pues indica que la variación de energía interna es igual a la cantidad de calor absorbido o liberado a volumen constante. La alternativa A sugiere que ΔU siempre es cero, lo cual solo ocurre en procesos isocalóricos sin transferencia de calor, lo cual no se garantiza en la pregunta. La opción B incluye un término w que, bajo volumen constante, es nulo, pero su presentación como q_v+w es redundante y confusa. La alternativa D asume que ΔU=ΔH, lo cual solo se cumple a presión constante, no a volumen constante. Por tanto, las respuestas A, B y D son incorrectas porque violan la condición de volumen constante o introducen términos innecesarios.'),
  (376, 'La ley de Henry establece que la concentración de un gas disuelto (C) es directamente proporcional a la presión parcial (P) del gas sobre la solución, con la constante de Henry (KH) como factor de proporcionalidad: C = P/KH; por lo tanto, cuanto mayor sea KH, menor será la solubilidad, lo que hace que la opción A sea la única que describe correctamente la relación inversa entre solubilidad y constante de Henry; las demás alternativas son incorrectas porque la opción B afirma una relación directa, contradiciendo la ecuación de Henry; la opción C es falsa pues la solubilidad sí varía con la presión; y la opción D confunde la relación, pues la solubilidad es directamente proporcional a la presión, no inversamente.'),
  (377, 'El riesgo de daño hepático grave tras una sobredosis de paracetamol aumenta en pacientes con inducción de citocromo P450 porque la vía de glucuronidación y sulfoconjugación, que son las rutas de desintoxicación preferentes, se saturan y el fármaco se descompone mayoritariamente por el metabolismo oxidativo, generando N‑acetil‑para‑aminofenol (NAPQI) tóxico; la glucosa‑6‑fosfato y el glutathión se agotan, lo que favorece la lesión hepática. En contraste, la opción A es incorrecta ya que el exceso de enzimas de sulfatación favorece la conjugación y reduce la formación de NAPQI, disminuyendo el riesgo; la opción C es errónea porque la deficiencia de glutathión aumenta el daño, no lo disminuye; y la opción D también es falsa, pues la inducción de las enzimas de glucuronidación mejora la eliminación del paracetamol y reduce el riesgo de hepatotoxicidad.'),
  (378, 'El compuesto 1‑metil‑4‑fenil‑1,2,3,6‑tetrahidropiridina (MPTP) se metaboliza en el hígado a 1‑metil‑4‑fenil‑1,2,3,6‑tetrahidropiridina‑3‑metil‑4‑oxona (MPP⁺), la forma activa que atraviesa la barrera hematoencefálica y se acumula en las neuronas dopaminérgicas de la sustancia negra; allí, MPP⁺ inhibe la cadena respiratoria del complejo I de la mitocondria, provocando generación de especies reactivas de oxígeno y muerte celular por apoptosis. Este mecanismo de neurotoxicidad es característico de la enfermedad de Parkinson y explica por qué las neuronas dopaminérgicas son las que sufren la lesión. Las otras opciones son incorrectas porque MPP⁺ no muestra afinidad ni efecto directo sobre receptores o transportadores de glutamato, serotonina o colina, y su toxicidad no implica alteraciones en estos sistemas neuronales.'),
  (379, 'El t‑butilo es el sustituyente más voluminoso de la lista; al situarse en la posición axial produciría interacciones 1,3‑di‑axiales de gran repulsión con los grupos vecinos, lo que incrementa el esfuerzo de torsión y eleva la energía de la conformación; por tanto, la conformación silla con el t‑butilo ecuatorial minimiza esas repulsiones y es la más estable, por lo que la preferencia por la posición ecuatorial es la mayor. El metil, aunque también es un sustituyente, es mucho más pequeño y su energía axial no se ve tan penalizada, de modo que puede adoptar la posición axial sin un aumento significativo de energía; el cloro, de tamaño intermedio, también puede tolerar la posición axial sin generar repulsiones tan severas; la hidroxilo, además de su tamaño moderado, puede formar enlaces de hidrógeno intramoleculares que favorecen la conformación axial, por lo que su preferencia por la posición ecuatorial es menor que la del t‑butilo.'),
  (380, 'La formación de carbocationes como intermedios de reacción se produce en reacciones de adición electrofílica a alquenos, donde el doble enlace actúa como nucleófilo y el agente electrofílico (por ejemplo, un halógeno o un ácido) ataca al carbono más electronegativo del doble enlace, generando un carbocation intermedio que luego puede ser atacado por un nucleófilo; en las sustituciones nucleofílicas bimoleculares sobre derivados halogenados (opción A) el mecanismo es SN2, con ataque directo al carbono y ruptura simultánea del enlace C–X, sin intermediario de carbocation; en la adición nucleofílica a cetonas (opción B) el nucleófilo ataca al carbonilo y el oxígeno permanece unido al carbono, no se forma un carbocation; y en la adición tipo Michael (opción C) el nucleófilo ataca a un doble enlace conjugado con un grupo electronattractor, pero el mecanismo es SN2 o SN2′, sin intermediario de carbocation.'),
  (381, 'La amina más básica entre las opciones es la N,N‑dietilamina (C) porque el par de grupos etilo en el nitrógeno aumenta la densidad electrónica y el efecto inductivo del carbono, elevando la densidad de electrones en el nitrógeno y, por tanto, su capacidad para aceptar protones; además, el nitrógeno está libre de sustituyentes aromáticos que puedan despolarizarlo, lo que no ocurre en la anilina (A) y la 4‑metilanilina (B) donde el anillo aromático con su efecto de resonancia disminuye la basicidad, y en la metilamina (D) el único grupo metilo aporta menos electrones que dos etilos, resultando en una basicidad menor.'),
  (382, 'La aminación reductora de un ácido alfa-ceto produce un aminoácido; el ácido que debe emplearse es el ácido 2‑oxopropanoico (ácido propiónico ceto), pues su estructura contiene el grupo ceto α‑alfa que, tras reducción con hidruro de níquel y sustitución de hidrógeno por amina, genera la alanina en forma racémica; el ácido 2‑cloropropanoico (B) es un halógeno que no permite la formación del grupo ceto necesario y su reacción con amoníaco produce cloraminas, no aminoácidos; el ácido 2‑hidroxipropanoico (C) carece del grupo ceto y su aminación no conduce a la alanina; el ácido 2‑oxobutanoico (D) lleva un carbono extra, lo que daría como producto un aminoácido de cadena más larga (valina), no la alanina.'),
  (383, 'El p‑clorofenol presenta el grupo hidroxilo orto‑para a un átomo de cloro, que es un electrófilo fuerte; el efecto inductivo del cloro retira electrones del anión fenolato, estabilizando la carga negativa y reduciendo el pKa, por lo que su acidez es mayor que la del etanol (un alcohol primario sin efecto inductivo) y mayor que la del 2,2,2‑trifluoroetanol, donde el grupo CF₃, aunque electronegativo, no está conjugado con un anillo aromático y el anión resultante es menos estable que el fenolato. El p‑aminofenol, por otro lado, tiene un grupo amino electron-donante que aumenta la densidad electrónica del anión fenolato, lo que lo hace menos estable y, por tanto, menos ácido. Así, la opción c) p‑clorofenol es la más ácida, mientras que las opciones a) y b) son menos ácidas por falta de conjugación aromática y la opción d) es aún menos ácida por el efecto donador del amino.'),
  (384, 'La energía reticular es mayor en el compuesto que presenta los iones con mayor carga y menor radio, porque la energía de formación de la red cristalina es proporcional al producto de las cargas y inversamente proporcional a la distancia entre los iones; en MgO los iones Mg²⁺ y O²⁻ son los más pequeños de la lista y tienen la mayor carga combinada, lo que produce la mayor atracción electrostática y, por tanto, la mayor energía reticular; en MgF₂ la carga es la misma pero el radio del fluoruro es mayor, reduciendo la atracción; en NaF y Na₂O los iones monovalentes (Na⁺) tienen un radio mayor y la carga combinada es menor, lo que disminuye la energía reticular, por lo que estas opciones son incorrectas.'),
  (385, 'En los metales la conductividad eléctrica disminuye al aumentar la temperatura porque el aumento térmico provoca mayor vibración de los átomos de la red cristalina, lo que incrementa la frecuencia de colisiones entre los electrones libres y los núcleos, reduciendo su movilidad y, por tanto, la conductividad; esta relación inversa es característica de los conductores metálicos y se explica por la teoría de la conducción de electrones libres. Las demás opciones son erróneas: la opción A asume una relación directa que se observa en semiconductores, no en metales; la opción C ignora el efecto de la temperatura, que es esencial en la conducción metálica; y la opción D es incorrecta porque la conductividad sí depende del número de electrones de valencia, ya que estos son los portadores de carga que participan en la conducción.'),
  (386, 'La capacidad de apantallamiento aumenta con la distancia radial y con el número cuántico azimutal, de modo que los orbitales 3s, situados más cercanos al núcleo y con l=0, presentan mayor apantallamiento que los 3p (l=1) y, a su vez, los 3d (l=2) tienen el menor apantallamiento; por lo tanto, la secuencia 3s > 3p > 3d es la que ordena correctamente las funciones orbitales según su capacidad de apantallamiento. La opción A es incorrecta porque compara orbitales de diferentes niveles principales sin considerar el efecto del número cuántico l; la opción B invierte el orden correcto al colocar 3s como el de menor apantallamiento; y la opción C es errónea porque asume igualdad de apantallamiento entre orbitales con distintos l dentro del mismo nivel principal, lo cual no ocurre.'),
  (387, 'La geometría cuadrada plana de XeF₄ requiere que el átomo central xenón tenga seis orbitales híbridos que formen un plano; esto se logra con la hibridación sp³d², donde cuatro orbitales sp³ se combinan con dos orbitales d para generar seis orbitales híbridos orientados a los vértices de un hexágono y a los dos pares de electrones no enlazantes, produciendo la disposición cuadrada con ángulos de 90°. La opción A (sp³d) produciría una geometría trigonal bipiramidal, la opción B (sp³) daría una tetraedrica, y la opción C (sp) una lineal; ninguno coincide con la estructura cuadrada plana observada.'),
  (388, 'El diagrama de tallo y hoja es una herramienta de estadística descriptiva que permite representar la distribución de frecuencias de una variable cuantitativa al organizar los valores numéricos en una tabla donde el “tallo” indica la parte de mayor peso (por ejemplo, las decenas) y las “hojas” los dígitos menos significativos, de modo que se conserva la información exacta de cada observación y se facilita la visualización de la forma de la distribución, sus valores centrales y la dispersión; por ello la opción C es la que describe correctamente su función. La alternativa A se refiere a una clasificación biológica de organismos y no a un método de análisis de datos; la B habla de medias y medianas de muestras de distintos tamaños, lo cual no corresponde a la estructura de tallo y hoja, que muestra la frecuencia de cada valor individual; la D menciona datos categóricos, mientras que el diagrama de tallo y hoja se aplica exclusivamente a variables cuantitativas.'),
  (389, 'En una distribución platicúrtica los valores presentan una mayor concentración en los extremos de la curva, de modo que la densidad de probabilidad se “alarga” en las colas y se vuelve más delgada en el centro, lo que provoca una mayor probabilidad de observar valores muy alejados de la media que en una distribución normal; por tanto, la opción B describe correctamente este comportamiento. Las demás alternativas son incorrectas: la A asume la forma simétrica y de campana de la normal, que no se cumple en la platicúrtica; la C indica una mayor acumulación en el centro, característica de una distribución leptocúrtica, no platicúrtica; y la D afirma que la distribución es siempre asimétrica, lo cual no es cierto, ya que la platicúrtica puede ser simétrica o asimétrica dependiendo de su origen.'),
  (390, 'La afirmación correcta es la D porque la varianza se define como el promedio de los cuadrados de las desviaciones de cada observación respecto a la media aritmética; es decir, se suman los cuadrados de las diferencias y se divide por el número de observaciones (o por n‑1 en muestra), lo que da la medida de dispersión cuadrática. La opción A es incorrecta porque la raíz cuadrada de la varianza da la desviación estándar, no la varianza. La B describe la desviación estándar como la media de las diferencias absolutas, lo cual no es la definición estándar; la desviación estándar se obtiene de la raíz cuadrada de la varianza, no de la media de las diferencias. La C confunde la varianza con la media de las diferencias sin elevar al cuadrado, lo que produciría una suma que tiende a cero por simetría, por lo que no representa la dispersión. Todas las alternativas A, B y C comparten el error de no incluir el cuadrado de las diferencias en el cálculo de la varianza.'),
  (391, 'Los percentiles son medidas de posición que indican el valor que separa un cierto porcentaje de la distribución, por lo que la opción A es incorrecta; los cuartiles son los percentiles 25, 50 y 75, es decir, tres valores que dividen la muestra ordenada en cuatro grupos de igual tamaño, lo que corresponde a la opción C; la opción B confunde cuartiles con quintiles, pues requeriría cinco valores para dividir en cinco grupos; la opción D mezcla la cantidad de valores y grupos, pues cuatro valores no pueden dividir la muestra en tres grupos iguales.'),
  (392, 'El acuerdo de riesgo compartido implica que el beneficio o el coste se ajusta en función de un resultado clínico o de uso que depende de la eficacia real del producto; por ello, la opción B, que describe un descuento fijo del 40 % negociado por la farmacia sin referencia a ningún resultado clínico o de eficacia, no cumple con la definición de riesgo compartido, sino que corresponde a un simple descuento comercial. En cambio, la opción A establece un descuento del 20 % condicionado a la superación de un volumen de compra, lo que implica un riesgo de demanda que se comparte entre la farmacia y el fabricante; la opción C describe un financiamiento del tratamiento a partir de un punto de uso concreto (el décimo ciclo de quimioterapia), vinculando el desembolso a la continuidad del tratamiento y, por tanto, a la eficacia del anticuerpo; y la opción D vincula el precio a un resultado clínico medible (el crecimiento de la altura del paciente), ajustando el coste según el beneficio terapéutico real, lo que también constituye un acuerdo de riesgo compartido.'),
  (393, 'El principio activo que no cuenta con biosimilar es el erlotinib, porque se trata de un fármaco de síntesis química (inhibidor de la tirosina quinasa EGFR) cuyo desarrollo y producción se basan en procesos químicos estandarizados, lo que elimina la necesidad de crear un producto biológico idéntico; en cambio, los demás compuestos citados son biológicos: el filgrastim es una proteína recombinante que se ha replicado con biosimilares, la insulina glargina es una analogía de insulina que también tiene versiones biosimilares, y la enoxaparina es un anticoagulante de origen biológico que se ha producido en forma biosimilar. Por tanto, las opciones A, C y D presentan biosimilares, mientras que la B no lo hace.'),
  (394, 'El Nomenclátor oficial de la prestación farmacéutica es la Base de Datos del Ministerio de Sanidad que recoge, actualiza y publica la información de los medicamentos que se incluyen en el Sistema Nacional de Salud, incluyendo sus nombres, presentaciones y precios; por eso la opción B describe con precisión su función. La alternativa A confunde el Nomenclátor con la Comisión de Nomenclatura de la AEMPS, que sí asigna la Denominación Común Española (DOE) a los principios activos, pero no es el propio Nomenclátor. La opción C se refiere a la Comisión de Nomenclatura, responsable de aprobar o rechazar nombres de fantasía, y no al registro de prestaciones. La alternativa D describe a la AEMPS, pero el Nomenclátor no es un departamento de la AEMPS ni se dedica a la evaluación de genéricos; esa función corresponde al Comité de Medicamentos Genéricos.'),
  (395, 'La afirmación A es la única que se ajusta a la normativa de buenas prácticas clínicas: el monitor, que suele ser un profesional independiente o de la entidad patrocinadora, no forma parte del equipo investigador del centro, ya que su función es supervisar el cumplimiento del protocolo y la normativa, sin participar en la toma de decisiones investigativas; en cambio, el investigador principal (opción B) es quien dirige el estudio, pero no necesariamente debe financiarlo, y la definición de “investigador principal” no incluye la responsabilidad de iniciar la financiación; el manual del investigador (opción C) es el documento que recoge la descripción del protocolo, pero no es el único lugar donde se detallan los objetivos y la organización, ya que estos también se encuentran en el protocolo y en el plan de estudio; finalmente, el monitor (opción D) no realiza el ensayo clínico en el centro, sino que vigila su correcta ejecución, por lo que su papel es de supervisión y no de ejecución directa.'),
  (396, 'La opción B es incorrecta porque la normativa de medicamentos de terapia avanzada exige que cualquier producto elaborado fuera de una instalación industrial certificada, incluso si se produce en un hospital, debe contar con una autorización de fabricación (registro de producto) y, en el caso de exportación, con la aprobación de la autoridad sanitaria del país receptor; la mera solicitud de otro hospital no elimina la necesidad de nuevas autorizaciones ni de cumplir con los requisitos de calidad, trazabilidad y control de riesgo. En cambio, la opción A describe correctamente la categoría de terapia avanzada, que abarca terapia génica, terapia celular somática, ingeniería tisular y combinaciones de estos, tal como lo establece la legislación. La opción C es coherente con la definición de terapia avanzada, pues un tejido no manipulado sustancialmente y usado con la misma función esencial en donante y receptor no se considera terapia avanzada, aunque involucre células. Finalmente, la opción D identifica adecuadamente a la terapia CAR‑T como un medicamento de terapia avanzada, ya que implica la modificación genética de células T para su uso terapéutico. Así, solo la alternativa B presenta un error en la interpretación de los requisitos regulatorios.'),
  (397, 'La afirmación es falsa, pues el reconocimiento de antígenos propios por los linfocitos T o B es un proceso fisiológico que mantiene el pool de células y no constituye por sí solo un desencadenante de enfermedad autoinmune; la ruptura de la tolerancia requiere factores adicionales como la activación de células presentadoras de antígeno con coestímulo, citocinas proinflamatorias, daño tisular o defectos en mecanismos de supresión (células T reguladoras, fagocitos de eliminación de apoptóseticos, etc.). Por ello la opción C es la única que refleja correctamente la fisiología de la tolerancia inmunológica. Las opciones A y D son incorrectas porque confunden la presencia de antígenos propios con la aparición de enfermedad autoinmune, y la opción B es errónea al afirmar que el repertorio de linfocitos es autorreactivo y que eso por sí solo causa autoinmunidad.'),
  (398, 'La presentación de antígenos vía endocítica se lleva a cabo por las moléculas del MHC de clase II; el complejo HLA‑DM actúa como editor, intercambiando la molécula CLIP (clasicalin) que inicialmente ocupa el sitio de unión del peptide con el peptide derivado del patógeno, mientras que HLA‑DQ es otra molécula de clase II que también participa en la presentación de estos péptidos, por lo que la combinación CLIP–HLA‑DM–HLA‑DQ constituye el conjunto esencial de moléculas que intervienen en el procesamiento y presentación de antígenos endocíticos. Las opciones A y C incluyen componentes que pertenecen al sistema de presentación de clase I (TAP, TAPasin, calreticulina, calnexina, cadena invariante, CD4) y por tanto no están implicados en la vía endocítica. La opción B menciona MHC II, calreticulina, ERP57 y CLIP, pero omite a HLA‑DM, que es indispensable para el intercambio de CLIP por el peptide, por lo que no cubre todo el proceso.'),
  (399, 'La vía clásica del complemento se inicia cuando el complejo antígeno‑inmunoglobulina (IgG o IgM) se une a la C1q; IgA no posee la capacidad de reclutar C1q, por lo que su presencia sobre una bacteria gram‑negativa no desencadenará la cascada inflamatoria; en cambio, la IgM sobre la bacteria gram‑positiva (A) y la IgG sobre la gram‑positiva (C) activan la vía clásica, y la proteína C reactiva (D) puede fijar C1q y también iniciar la cascada, aunque de forma alternativa. Las demás opciones comparten el error de suponer que IgA puede activar la vía clásica, lo cual no ocurre.'),
  (400, 'La característica distintiva de las células T de memoria es que permanecen en estado quiescente tras la eliminación del antígeno, pero poseen una capacidad de respuesta aumentada y más rápida cuando el mismo antígeno vuelve a presentarse, lo que les permite iniciar una respuesta inmune secundaria con mayor velocidad y eficacia; esta propiedad se explica por la expresión de receptores de superficie con mayor afinidad y la disponibilidad de vías de señalización preactivadas que facilitan la proliferación y diferenciación. Por tanto, la opción C resume adecuadamente ambos rasgos. Las opciones A y B son incorrectas porque A describe una proliferación constante sin antígeno, lo cual no ocurre en las células de memoria, y B añade la idea de que son responsables de la autoinmunidad, una afirmación no respaldada por la fisiología de la memoria inmunológica; la opción D es errónea porque las células de memoria no son inmortales y su función principal no es activar a las células T vírgenes mediante secreción de citocinas, sino responder de manera más rápida al antígeno ya reconocido.'),
  (401, 'Los monocitos son la población leucocitaria que circula en sangre y que, al migrar a los tejidos, se diferencian en macrófagos funcionales; su capacidad de fagocitosis, presentación de antígenos y producción de citocinas los convierte en la fuente principal de macrófagos tisulares, mientras que los neutrófilos son efímeros y no se diferencian en macrófagos, los macrófagos inmaduros ya son macrófagos en proceso de maduración y no se originan en la sangre, y las células mieloides progenitoras circulantes son precursores de varias líneas celulares pero no se diferencian directamente en macrófagos en los tejidos.'),
  (402, 'El timo es el órgano linfoide primario donde los linfocitos T inmaduros, originados en la médula ósea, migran y completan su maduración; allí adquieren la capacidad de reconocer antígenos presentados por células de la propia familia MHC y se someten a procesos de selección positiva y negativa que eliminan los clones autoreactivos, permitiendo la generación de linfocitos T funcionales y tolerantes; la opción D refleja esta función esencial de maduración y selección, mientras que la A es incorrecta porque la muerte de linfocitos T senescentes ocurre en órganos secundarios como el bazo y el ganglio linfático; la B es falsa porque los linfocitos de memoria residen en tejidos periféricos y no en el timo; la C confunde la activación con la maduración, pues la activación de linfocitos T específica para un antígeno se produce en órganos secundarios tras la exposición al antígeno, no en el timo.'),
  (403, 'Las células dendríticas son células presentadoras de antígenos que, al capturar partículas patógenas en el tejido periférico, procesan los antígenos y migran a los ganglios linfáticos; allí, los presentan a los linfocitos T con el objetivo de iniciar la respuesta adaptativa, por lo que la alternativa que describe este proceso es la C. La opción A es incorrecta porque, aunque las células dendríticas pueden fagocitar microbios, su función principal no es erradicarlos sino presentarlos; además, no secretan citocinas inflamatorias de forma predominante para fomentar la inflamación local. La B es falsa porque no generan citocinas antiinflamatorias para activar a los linfocitos T; su migración se dirige a los ganglios linfáticos pero la producción de citocinas antiinflamatorias no es su función principal. La D es errónea porque la presentación de antígenos a los linfocitos T ocurre en los ganglios linfáticos, no en el sitio de infección.'),
  (404, 'Los linfocitos CD4+ Th17 son una subpoblación de células T helper que se diferencian bajo la influencia de citocinas IL‑6, IL‑21 y TGF‑β, y su función principal es la producción de IL‑17 (y otras citocinas proinflamatorias como IL‑21 y IL‑22), lo que potencia la respuesta inflamatoria al reclutar neutrófilos y promover la liberación de mediadores inflamatorios en tejidos afectados; por tanto la alternativa que indica la producción de IL‑17 y la inducción de una respuesta inflamatoria (opción C) describe fielmente su papel fisiológico. Las demás opciones son erróneas porque, aunque los linfocitos Th17 sí pueden secretar IL‑1, no es su citocina característica ni su función principal, y la opción A incluye IL‑7, que no se asocia con la vía Th17; la opción B presenta la respuesta antiinflamatoria, lo cual contradice el perfil proinflamatorio de esta subpoblación, y la opción D mezcla la producción de IL‑17 con una respuesta antiinflamatoria, lo que también es inconsistente con la biología de los Th17.'),
  (405, 'Para diseñar un agente ansiolítico se prefiere la 1,4‑benzodiazepina, ya que el anillo de diazepina con sustitución en los anillos B y C y la posición 1,4 permite la unión a los receptores GABA‑A con afinidad y selectividad que generan la sedación y la reducción de la ansiedad, como se evidencia en los fármacos clínicamente usados; la estructura 1,2‑benzodiazepina (opción C) carece de la conformación necesaria para la interacción con el sitio de unión del GABA, mientras que la fenotiazina (A) y la dibenzo[b,f]azepina (B) pertenecen a clases con mecanismos de acción distintos (antipsicóticos y antidepresivos, respectivamente) y no poseen la actividad ansiolítica característica de las benzodiazepinas.'),
  (406, 'Listeria monocytogenes es un bacilo grampositivo que se caracteriza por ser catalasa y CAMP positivo, lo que facilita su identificación en laboratorio; además, posee resistencia intrínseca a la ceftriaxona, reflejo de su falta de penicilina-binding proteins que son blanco de las cefalosporinas de tercera generación, razón por la cual la ceftriaxona no es eficaz contra esta bacteria. La afirmación que indica que no crece en hemocultivos es falsa, porque Listeria es un patógeno que frecuentemente se detecta en cultivos de sangre de pacientes con septicemia, especialmente en inmunocomprometidos, y su crecimiento en medios de hemocultivos es bien documentado; las demás opciones describen características microbiológicas y farmacológicas aceptadas de la especie.'),
  (407, 'El reflejo fotomotor, que regula la constricción de la pupila en respuesta a la luz, se origina en los fotorreceptores de la retina y sigue el nervio óptico hasta el pretectum, donde las fibras sinapsan con neuronas pretectales; estas neuronas proyectan bilateralmente a los núcleos de Edinger‑Westphal, que son los centros de salida parasimpáticas que inervan el músculo ciliar y el esfínter pupilar, por lo que la opción B es la que describe el núcleo implicado; el núcleo geniculado (A) participa en la transmisión visual a la corteza, el núcleo ciliespinal de Budge (C) no existe en la anatomía ocular y el núcleo de Deiters (D) está asociado a la vía auditiva, por lo que las alternativas A, C y D corresponden a estructuras que no participan en el reflejo fotomotor.'),
  (408, 'La caída de plaquetas a 87.000/µL a los siete días de tratamiento con heparina no fraccionada indica la aparición de heparina‑induced thrombocytopenia (HIT), una reacción inmunológica mediada por anticuerpos IgG contra el complejo heparina‑PF4 que provoca destrucción de plaquetas y un riesgo de trombosis; por ello la heparina debe suspenderse inmediatamente y sustituirse por un anticoagulante alternativo que no genere anticuerpos, siendo el fondaparinux la opción recomendada por su alta especificidad y bajo riesgo de re‑inducción de HIT. La opción A (sulfato de protamina) solo neutraliza la heparina en la sangre y no evita la respuesta inmunológica ni la trombosis, por lo que no es adecuada. La opción B (heparina de bajo peso molecular) sigue siendo un heparino y puede desencadenar o empeorar la HIT, por lo que no se aconseja. La opción C (concentrado de plaquetas) no corrige la causa subyacente y aumenta el riesgo trombótico, además de no prevenir la progresión de la HIT.'),
  (409, 'La vancomicina no pertenece al grupo de los lipopéptidos; es un glicopéptido, compuesto por una cadena de péptidos y un anillo de glicina, y su estructura química difiere significativamente de la de la teicoplanina, que sí es lipopéptido; por ello la afirmación A es la única que se aparta de la realidad farmacológica. Las demás opciones describen hechos verídicos: la vancomicina se administra por vía oral para tratar la colitis por Clostridioides difficile porque su biodisponibilidad sistémica es baja y permanece activo en el lumen intestinal; los efectos adversos típicos incluyen exantemas, ototoxicidad y nefrotoxicidad, reflejo de su alta concentración en tejidos y su capacidad para interferir con la función renal y auditiva; y su mecanismo de acción consiste en la inhibición de la síntesis de la pared celular bacteriana al unirse a la terminación D-Ala-D-Ala de los precursores peptidoglicanos, bloqueando la transpeptidación y la formación de la pared.'),
  (410, 'Diclofenaco presenta la mayor afinidad por la enzima COX‑2 entre los fármacos indicados, ya que su estructura aromática con dos grupos carboxilato y un anillo benceno con un sustituyente metil permite una mayor interacción con el sitio activo de la COX‑2, reduciendo la síntesis de prostaglandinas inflamatorias sin alterar significativamente la síntesis de prostaglandinas protectoras del estómago; en contraste, el ácido acetilsalicílico, el ibuprofeno y el naproxeno son inhibidores no selectivos con mayor afinidad por la COX‑1, lo que explica su mayor incidencia de efectos gastrointestinales. Las opciones A, B y C comparten el mismo error de confundir la selectividad entre las dos isoformas de la ciclooxigenasa, mientras que la opción D se diferencia por su mayor afinidad por la COX‑2.'),
  (411, 'La vía oral presenta la mayor pérdida por metabolización hepática porque el fármaco ingresa al tracto gastrointestinal, es absorbido en el intestino y luego transportado al hígado a través de la vena porta, donde sufre el primer paso de metabolismo hepático (fase I y II), reduciendo significativamente su biodisponibilidad; en cambio, la vía transpulmonar permite una absorción directa al torrente sistémico con escasa exposición al hígado, la percutánea evita el sistema portal y la rectal, aunque parcialmente, evita el primer paso hepático, por lo que las otras opciones presentan menor pérdida.'),
  (412, 'La prealbúmina, también conocida como transtiretina, es una proteína de transporte de tiroides y retinol que se sintetiza en el hígado y tiene una vida media muy corta; su concentración plasmática suele medirse en pruebas de nutrición o función hepática, pero no se incluye habitualmente en el proteinograma de suero, que se centra en las proteínas globulinas (Ig, haptoglobina, etc.) y la albúmina; por el contrario, la haptoglobina es una globulina que se mide en el proteinograma para valorar la hemólisis y la inflamación, la ferroxidasa (ferroxidasa de hierro) se detecta en el análisis de hierro sérico y la proteína transportadora de retinol (transtiretina) sí aparece en el proteinograma como una de las globulinas de bajo peso molecular, por lo que las opciones B, C y D sí se observan.'),
  (413, 'El espectro de masas muestra la abundancia relativa de los iones en función de su relación masa/carga (m/z), ya que el separador de iones en el espectrómetro se basa en la aceleración de iones con una carga determinada y la deflexión de su trayectoria depende de su masa; por tanto, la posición de cada pico se interpreta como la relación masa/carga, no simplemente la masa ni la carga aislada, y la opción C refleja esa dependencia. Las opciones A y B son incorrectas porque la intensidad de los picos no se relaciona con la carga ni con la masa individualmente, sino con su combinación; la opción D es errónea porque invierte la relación, describiendo carga/masa, lo cual no corresponde al eje horizontal del espectro.'),
  (414, 'El antídoto indicado en una sobredosis de anticoagulantes de la clase de la warfarina es la vitamina K, ya que su administración reanuda la síntesis hepática de factores de coagulación dependientes de vitamina K (II, VII, IX y X), reduciendo de manera efectiva el INR y restaurando la coagulación; los otros fármacos citados no actúan sobre la vía de la warfarina: el idarucizumab es un anticuerpo monoclonal que neutraliza la anticoagulación de dabigatrán, un inhibidor directo del factor Xa, el flumazenilo es un antagonista de los receptores GABA‑A utilizado para reverter los efectos de benzodiacepinas, y el andexanet es un decoy receptor que bloquea los anticoagulantes orales de la familia de los inhibidores del factor Xa, por lo que ninguno de ellos corrige la deficiencia de vitamina K ni la reducción de los factores de coagulación inducida por la warfarina.')
) AS v(id, explicacion)
WHERE p.id = v.id;

DO $$
DECLARE
  sin_explicacion_despues int;
BEGIN
  SELECT COUNT(*) INTO sin_explicacion_despues
    FROM public.preguntas WHERE explicacion IS NULL OR explicacion = '';
  IF sin_explicacion_despues != 0 THEN
    RAISE EXCEPTION '% preguntas se quedaron sin explicacion -- abortando.', sin_explicacion_despues;
  END IF;
  RAISE NOTICE 'OK: 0 preguntas sin explicacion.';
END $$;

COMMIT;
